 {id:"en-w-fin-loan",title:"Tư vấn khoản vay",scene:"Một chủ cửa hàng đến ngân hàng hỏi vay vốn. Bạn là nhân viên tín dụng.",partner:"Khách hàng",ind:"fin",work:true,lines:[{r:"A",t:"Hi, I'd like to borrow some money to expand my shop.",v:"Chào bạn, tôi muốn vay một khoản để mở rộng cửa hàng."},{r:"B",t:"Of course. How much would you like to borrow?",v:"Vâng ạ. Anh muốn vay bao nhiêu?"},{r:"A",t:"About fifty thousand dollars.",v:"Khoảng năm mươi nghìn đô."},{r:"B",t:"And how long do you need to pay it back?",v:"Còn anh cần trả trong bao lâu?"},{r:"A",t:"Maybe three years. What's the interest rate?",v:"Chắc ba năm. Lãi suất là bao nhiêu?"},{r:"B",t:"For a three-year business loan, it's eight percent a year.",v:"Với khoản vay kinh doanh ba năm, lãi suất là tám phần trăm một năm."},{r:"A",t:"Do I need any collateral?",v:"Tôi có cần tài sản thế chấp không?"},{r:"B",t:"Yes, we'll need collateral and your financial statements for the last two years.",v:"Có ạ, chúng tôi cần tài sản thế chấp và báo cáo tài chính hai năm gần nhất của anh."},{r:"A",t:"No problem. I'll bring them next week.",v:"Không vấn đề gì. Tuần sau tôi mang đến."},{r:"B",t:"Great. Here's the application form.",v:"Tốt quá. Đây là đơn đăng ký."}],phrases:[{t:"Of course. How much would you like to borrow?",v:"Vâng ạ. Anh muốn vay bao nhiêu?"},{t:"And how long do you need to pay it back?",v:"Còn anh cần trả trong bao lâu?"},{t:"For a three-year business loan, it's eight percent a year.",v:"Với khoản vay kinh doanh ba năm, lãi suất là tám phần trăm một năm."},{t:"Yes, we'll need collateral and your financial statements for the last two years.",v:"Có ạ, chúng tôi cần tài sản thế chấp và báo cáo tài chính hai năm gần nhất của anh."}],notes:[{h:"would like to: cách nói lịch sự",b:"Nhân viên dùng \"How much would you like to...?\" thay cho \"How much do you want?\" để lịch sự hơn với khách."},{h:"Nói phần trăm và số tiền",b:"8% đọc là \"eight percent\". 50,000 đọc là \"fifty thousand\". Không thêm \"s\" sau thousand khi có số đứng trước."}]},
 {id:"en-w-fin-report",title:"Báo cáo kết quả quý",scene:"Bạn trình bày kết quả kinh doanh quý trong cuộc họp với giám đốc.",partner:"Giám đốc",ind:"fin",work:true,lines:[{r:"A",t:"Let's start. How did we do this quarter?",v:"Bắt đầu nhé. Quý này chúng ta làm ăn thế nào?"},{r:"B",t:"Revenue increased by twelve percent compared to last quarter.",v:"Doanh thu tăng mười hai phần trăm so với quý trước."},{r:"A",t:"That's good. What about costs?",v:"Tốt đấy. Còn chi phí thì sao?"},{r:"B",t:"Costs went up slightly, mainly because of marketing.",v:"Chi phí tăng nhẹ, chủ yếu do marketing."},{r:"A",t:"So what's our net profit?",v:"Vậy lợi nhuận ròng của chúng ta là bao nhiêu?"},{r:"B",t:"Net profit was two point five million dollars, up eight percent.",v:"Lợi nhuận ròng là hai phẩy năm triệu đô, tăng tám phần trăm."},{r:"A",t:"And cash flow?",v:"Còn dòng tiền?"},{r:"B",t:"Cash flow is healthy. We have enough cash for the next six months.",v:"Dòng tiền ổn định. Chúng ta đủ tiền mặt cho sáu tháng tới."},{r:"A",t:"Good work. Please send me the full report.",v:"Làm tốt lắm. Gửi tôi báo cáo đầy đủ nhé."},{r:"B",t:"Sure, I'll email it this afternoon.",v:"Vâng, chiều nay tôi sẽ gửi email."}],phrases:[{t:"Revenue increased by twelve percent compared to last quarter.",v:"Doanh thu tăng mười hai phần trăm so với quý trước."},{t:"Costs went up slightly, mainly because of marketing.",v:"Chi phí tăng nhẹ, chủ yếu do marketing."},{t:"Net profit was two point five million dollars, up eight percent.",v:"Lợi nhuận ròng là hai phẩy năm triệu đô, tăng tám phần trăm."},{t:"Cash flow is healthy. We have enough cash for the next six months.",v:"Dòng tiền ổn định. Chúng ta đủ tiền mặt cho sáu tháng tới."}],notes:[{h:"Mô tả tăng giảm",b:"increase / go up = tăng, decrease / go down = giảm. \"by 12%\" là tăng thêm 12%. \"slightly\" là nhẹ, \"sharply\" là mạnh."},{h:"Đọc số thập phân",b:"2.5 đọc là \"two point five\". Dùng dấu chấm cho số thập phân trong tiếng Anh, khác tiếng Việt dùng dấu phẩy."}]},
 {id:"en-w-fin-invest",title:"Tư vấn đầu tư",scene:"Một khách hàng muốn đầu tư tiền tiết kiệm. Bạn là chuyên viên tư vấn.",partner:"Khách hàng",ind:"fin",work:true,lines:[{r:"A",t:"I have some savings. Where should I invest?",v:"Tôi có ít tiền tiết kiệm. Tôi nên đầu tư vào đâu?"},{r:"B",t:"First, how much risk are you comfortable with?",v:"Trước hết, anh chấp nhận rủi ro ở mức nào?"},{r:"A",t:"Not too much. I don't want to lose money.",v:"Không nhiều lắm. Tôi không muốn mất tiền."},{r:"B",t:"Then I'd suggest a mix of bonds and a few safe stocks.",v:"Vậy tôi gợi ý kết hợp trái phiếu và một ít cổ phiếu an toàn."},{r:"A",t:"What return can I expect?",v:"Tôi có thể kỳ vọng lợi nhuận bao nhiêu?"},{r:"B",t:"Around five to seven percent a year, but it's not guaranteed.",v:"Khoảng năm đến bảy phần trăm một năm, nhưng không được đảm bảo."},{r:"A",t:"How long should I keep the money there?",v:"Tôi nên để tiền ở đó bao lâu?"},{r:"B",t:"It's best to invest for at least three to five years.",v:"Tốt nhất nên đầu tư ít nhất ba đến năm năm."},{r:"A",t:"OK. Can you send me some options?",v:"Được. Bạn gửi tôi vài phương án nhé?"},{r:"B",t:"Of course. I'll prepare a plan for you.",v:"Tất nhiên. Tôi sẽ chuẩn bị kế hoạch cho anh."}],phrases:[{t:"First, how much risk are you comfortable with?",v:"Trước hết, anh chấp nhận rủi ro ở mức nào?"},{t:"Then I'd suggest a mix of bonds and a few safe stocks.",v:"Vậy tôi gợi ý kết hợp trái phiếu và một ít cổ phiếu an toàn."},{t:"Around five to seven percent a year, but it's not guaranteed.",v:"Khoảng năm đến bảy phần trăm một năm, nhưng không được đảm bảo."},{t:"It's best to invest for at least three to five years.",v:"Tốt nhất nên đầu tư ít nhất ba đến năm năm."}],notes:[{h:"I'd suggest... để gợi ý",b:"\"I'd suggest + danh từ\" hoặc \"I'd recommend + V-ing\" nghe chuyên nghiệp và mềm mỏng hơn \"You should...\"."},{h:"Nói về rủi ro",b:"Luôn nói rõ \"it's not guaranteed\" (không đảm bảo) khi nói về lợi nhuận đầu tư. Đây là thói quen bắt buộc của người tư vấn."}]},
 {id:"en-w-acc-invoice",title:"Hỏi về hóa đơn",scene:"Một đồng nghiệp nộp chi phí công tác. Bạn là kế toán.",partner:"Đồng nghiệp",ind:"acc",work:true,lines:[{r:"A",t:"Hi, I'd like to claim my travel expenses.",v:"Chào chị, em muốn thanh toán chi phí công tác."},{r:"B",t:"Sure. Do you have the receipts?",v:"Được. Em có hóa đơn không?"},{r:"A",t:"Yes, here are the hotel and taxi receipts.",v:"Có ạ, đây là hóa đơn khách sạn và taxi."},{r:"B",t:"The hotel invoice needs the company's tax code.",v:"Hóa đơn khách sạn cần có mã số thuế của công ty."},{r:"A",t:"Oh, I didn't know that. What should I do?",v:"Ồ, em không biết. Em nên làm gì ạ?"},{r:"B",t:"Please ask the hotel to issue a new invoice.",v:"Em nhờ khách sạn xuất lại hóa đơn mới nhé."},{r:"A",t:"OK. When will I get paid?",v:"Vâng. Khi nào em được nhận tiền ạ?"},{r:"B",t:"We process payments every Friday, so next Friday at the latest.",v:"Bên chị thanh toán vào thứ Sáu hằng tuần, nên chậm nhất là thứ Sáu tới."},{r:"A",t:"Thank you so much.",v:"Cảm ơn chị nhiều."}],phrases:[{t:"Sure. Do you have the receipts?",v:"Được. Em có hóa đơn không?"},{t:"The hotel invoice needs the company's tax code.",v:"Hóa đơn khách sạn cần có mã số thuế của công ty."},{t:"Please ask the hotel to issue a new invoice.",v:"Em nhờ khách sạn xuất lại hóa đơn mới nhé."},{t:"We process payments every Friday, so next Friday at the latest.",v:"Bên chị thanh toán vào thứ Sáu hằng tuần, nên chậm nhất là thứ Sáu tới."}],notes:[{h:"receipt và invoice",b:"receipt là biên lai đã trả tiền. invoice là hóa đơn đòi tiền hoặc hóa đơn có thông tin thuế. Trong công ty Việt Nam, \"hóa đơn đỏ\" thường gọi là VAT invoice."},{h:"at the latest",b:"\"next Friday at the latest\" là chậm nhất thứ Sáu tới. Ngược lại: \"at the earliest\" là sớm nhất."}]},
 {id:"en-w-acc-close",title:"Chốt sổ cuối tháng",scene:"Trưởng phòng kế toán hỏi tiến độ chốt sổ.",partner:"Trưởng phòng",ind:"acc",work:true,lines:[{r:"A",t:"Are we ready to close the books for this month?",v:"Chúng ta đã sẵn sàng chốt sổ tháng này chưa?"},{r:"B",t:"Almost. I'm still checking the bank reconciliation.",v:"Gần xong rồi ạ. Em vẫn đang đối chiếu với sao kê ngân hàng."},{r:"A",t:"Is there a problem?",v:"Có vấn đề gì không?"},{r:"B",t:"There's a difference of two hundred dollars. I think it's a bank fee.",v:"Có chênh lệch hai trăm đô. Em nghĩ đó là phí ngân hàng."},{r:"A",t:"OK. What about accounts receivable?",v:"Được. Còn các khoản phải thu?"},{r:"B",t:"Three customers haven't paid yet. I sent them reminders yesterday.",v:"Ba khách hàng chưa thanh toán. Hôm qua em đã gửi thư nhắc."},{r:"A",t:"Good. Can you finish everything by Wednesday?",v:"Tốt. Em hoàn thành hết trước thứ Tư được không?"},{r:"B",t:"Yes, I'll send you the balance sheet on Wednesday morning.",v:"Được ạ, sáng thứ Tư em sẽ gửi chị bảng cân đối kế toán."}],phrases:[{t:"Almost. I'm still checking the bank reconciliation.",v:"Gần xong rồi ạ. Em vẫn đang đối chiếu với sao kê ngân hàng."},{t:"There's a difference of two hundred dollars. I think it's a bank fee.",v:"Có chênh lệch hai trăm đô. Em nghĩ đó là phí ngân hàng."},{t:"Three customers haven't paid yet. I sent them reminders yesterday.",v:"Ba khách hàng chưa thanh toán. Hôm qua em đã gửi thư nhắc."},{t:"Yes, I'll send you the balance sheet on Wednesday morning.",v:"Được ạ, sáng thứ Tư em sẽ gửi chị bảng cân đối kế toán."}],notes:[{h:"close the books",b:"\"Close the books\" là chốt sổ cuối kỳ. \"Books\" ở đây là sổ sách kế toán, không phải sách."},{h:"haven't + V3 với yet",b:"\"haven't paid yet\" là chưa trả. Dùng thì hiện tại hoàn thành cho việc tính đến bây giờ vẫn chưa xảy ra."}]},
 {id:"en-w-acc-audit",title:"Làm việc với kiểm toán viên",scene:"Kiểm toán viên độc lập đến kiểm tra sổ sách công ty bạn.",partner:"Kiểm toán viên",ind:"acc",work:true,lines:[{r:"A",t:"Good morning. We'd like to look at your sales records for last year.",v:"Chào buổi sáng. Chúng tôi muốn xem sổ doanh thu năm ngoái của công ty."},{r:"B",t:"Of course. I've prepared all the files in this folder.",v:"Vâng. Tôi đã chuẩn bị toàn bộ hồ sơ trong thư mục này."},{r:"A",t:"Thank you. Can you explain this large payment in March?",v:"Cảm ơn. Anh giải thích giúp khoản thanh toán lớn này vào tháng Ba?"},{r:"B",t:"That was for new equipment. Here is the contract and the invoice.",v:"Đó là tiền mua thiết bị mới. Đây là hợp đồng và hóa đơn."},{r:"A",t:"How do you calculate depreciation?",v:"Công ty tính khấu hao thế nào?"},{r:"B",t:"We use the straight-line method over five years.",v:"Chúng tôi dùng phương pháp đường thẳng trong năm năm."},{r:"A",t:"I see. We may have more questions tomorrow.",v:"Tôi hiểu rồi. Có thể ngày mai chúng tôi còn câu hỏi."},{r:"B",t:"No problem. You can contact me anytime.",v:"Không vấn đề gì. Anh cứ liên hệ tôi bất cứ lúc nào."}],phrases:[{t:"Of course. I've prepared all the files in this folder.",v:"Vâng. Tôi đã chuẩn bị toàn bộ hồ sơ trong thư mục này."},{t:"That was for new equipment. Here is the contract and the invoice.",v:"Đó là tiền mua thiết bị mới. Đây là hợp đồng và hóa đơn."},{t:"We use the straight-line method over five years.",v:"Chúng tôi dùng phương pháp đường thẳng trong năm năm."},{t:"No problem. You can contact me anytime.",v:"Không vấn đề gì. Anh cứ liên hệ tôi bất cứ lúc nào."}],notes:[{h:"Chuẩn bị trước bằng thì hiện tại hoàn thành",b:"\"I've prepared...\" cho thấy việc đã làm xong và sẵn sàng. Kiểm toán viên đánh giá cao sự chủ động này."},{h:"Luôn có chứng từ đi kèm",b:"Khi giải thích một khoản chi, đưa ngay chứng từ: \"Here is the contract and the invoice.\""}]},
 {id:"en-w-sales-call",title:"Gọi điện chào hàng",scene:"Bạn gọi cho một công ty để giới thiệu phần mềm quản lý bán hàng.",partner:"Khách hàng tiềm năng",ind:"sales",work:true,lines:[{r:"A",t:"Hello, this is Mark speaking.",v:"A lô, Mark nghe đây."},{r:"B",t:"Hi Mark, my name is Linh from Smart Sales. Do you have two minutes?",v:"Chào anh Mark, em là Linh bên Smart Sales. Anh có hai phút không ạ?"},{r:"A",t:"Sure, what is it about?",v:"Được, chuyện gì vậy?"},{r:"B",t:"We help shops manage their sales and stock in one app.",v:"Bên em giúp các cửa hàng quản lý bán hàng và tồn kho trong một ứng dụng."},{r:"A",t:"We already use Excel for that.",v:"Bên tôi dùng Excel rồi."},{r:"B",t:"Many of our clients did too. Our app saves them about ten hours a week.",v:"Nhiều khách hàng của em trước đây cũng vậy. Ứng dụng giúp họ tiết kiệm khoảng mười giờ mỗi tuần."},{r:"A",t:"Hmm, how much does it cost?",v:"Hừm, giá bao nhiêu?"},{r:"B",t:"It starts at thirty dollars a month. Can I show you a free demo next week?",v:"Từ ba mươi đô một tháng. Tuần sau em giới thiệu thử miễn phí cho anh được không ạ?"},{r:"A",t:"OK, Tuesday morning works for me.",v:"Được, sáng thứ Ba tôi rảnh."},{r:"B",t:"Great, I'll send you an invitation. Thank you, Mark!",v:"Tuyệt, em sẽ gửi lời mời. Cảm ơn anh Mark!"}],phrases:[{t:"Hi Mark, my name is Linh from Smart Sales. Do you have two minutes?",v:"Chào anh Mark, em là Linh bên Smart Sales. Anh có hai phút không ạ?"},{t:"We help shops manage their sales and stock in one app.",v:"Bên em giúp các cửa hàng quản lý bán hàng và tồn kho trong một ứng dụng."},{t:"Many of our clients did too. Our app saves them about ten hours a week.",v:"Nhiều khách hàng của em trước đây cũng vậy. Ứng dụng giúp họ tiết kiệm khoảng mười giờ mỗi tuần."},{t:"It starts at thirty dollars a month. Can I show you a free demo next week?",v:"Từ ba mươi đô một tháng. Tuần sau em giới thiệu thử miễn phí cho anh được không ạ?"}],notes:[{h:"Hỏi xin thời gian trước",b:"\"Do you have two minutes?\" tôn trọng thời gian của người nghe, giúp cuộc gọi dễ được tiếp tục."},{h:"Trả lời lời từ chối bằng câu chuyện khách hàng",b:"\"Many of our clients did too\" là cách đồng cảm rồi đưa ra lợi ích cụ thể bằng con số."}]},
 {id:"en-w-sales-nego",title:"Đàm phán giá",scene:"Khách hàng muốn đặt số lượng lớn và đề nghị giảm giá.",partner:"Khách hàng",ind:"sales",work:true,lines:[{r:"A",t:"We want to order five hundred units. Can you give us a better price?",v:"Chúng tôi muốn đặt năm trăm sản phẩm. Bên anh giảm giá được không?"},{r:"B",t:"For five hundred units, we can offer a five percent discount.",v:"Với năm trăm sản phẩm, bên em có thể giảm năm phần trăm."},{r:"A",t:"That's not enough. Another supplier offered ten percent.",v:"Như vậy chưa đủ. Một nhà cung cấp khác giảm mười phần trăm."},{r:"B",t:"I understand. If you order one thousand units, we can give you eight percent.",v:"Em hiểu. Nếu anh đặt một nghìn sản phẩm, bên em giảm tám phần trăm."},{r:"A",t:"What about delivery?",v:"Còn giao hàng thì sao?"},{r:"B",t:"Delivery is free, and we can deliver within two weeks.",v:"Miễn phí giao hàng, và bên em giao trong vòng hai tuần."},{r:"A",t:"And the payment terms?",v:"Còn điều khoản thanh toán?"},{r:"B",t:"Thirty percent deposit, and the rest within thirty days.",v:"Đặt cọc ba mươi phần trăm, phần còn lại trong vòng ba mươi ngày."},{r:"A",t:"OK, let me discuss it with my team.",v:"Được, để tôi bàn với nhóm."},{r:"B",t:"Of course. I'll send you the quotation today.",v:"Vâng ạ. Hôm nay em gửi anh bảng báo giá."}],phrases:[{t:"For five hundred units, we can offer a five percent discount.",v:"Với năm trăm sản phẩm, bên em có thể giảm năm phần trăm."},{t:"I understand. If you order one thousand units, we can give you eight percent.",v:"Em hiểu. Nếu anh đặt một nghìn sản phẩm, bên em giảm tám phần trăm."},{t:"Delivery is free, and we can deliver within two weeks.",v:"Miễn phí giao hàng, và bên em giao trong vòng hai tuần."},{t:"Thirty percent deposit, and the rest within thirty days.",v:"Đặt cọc ba mươi phần trăm, phần còn lại trong vòng ba mươi ngày."}],notes:[{h:"Đổi điều kiện thay vì chỉ giảm giá",b:"\"If you..., we can...\" là cấu trúc đàm phán: muốn được thêm thì bên kia cũng phải cho thêm."},{h:"payment terms",b:"Điều khoản thanh toán thường gồm tiền cọc (deposit) và thời hạn trả phần còn lại."}]},
 {id:"en-w-sales-complaint",title:"Xử lý khiếu nại",scene:"Một khách hàng gọi đến phàn nàn vì giao hàng trễ.",partner:"Khách hàng",ind:"sales",work:true,lines:[{r:"A",t:"My order is a week late. This is not acceptable.",v:"Đơn hàng của tôi trễ một tuần rồi. Thế này không thể chấp nhận được."},{r:"B",t:"I'm very sorry about that. Can I have your order number, please?",v:"Em rất xin lỗi về việc này. Anh cho em xin mã đơn hàng được không ạ?"},{r:"A",t:"It's A-four-five-two.",v:"Mã là A452."},{r:"B",t:"Thank you. I can see there was a problem at our warehouse.",v:"Cảm ơn anh. Em thấy có sự cố ở kho bên em."},{r:"A",t:"So when will I get it?",v:"Vậy khi nào tôi nhận được?"},{r:"B",t:"We'll send it by express delivery today. You'll get it tomorrow.",v:"Hôm nay bên em gửi chuyển phát nhanh. Ngày mai anh sẽ nhận được."},{r:"A",t:"OK. But I'm still not happy.",v:"Được. Nhưng tôi vẫn không hài lòng."},{r:"B",t:"I understand. We'll give you a ten percent discount on your next order.",v:"Em hiểu ạ. Bên em sẽ giảm mười phần trăm cho đơn hàng tiếp theo của anh."},{r:"A",t:"Alright, thank you.",v:"Thôi được, cảm ơn."}],phrases:[{t:"I'm very sorry about that. Can I have your order number, please?",v:"Em rất xin lỗi về việc này. Anh cho em xin mã đơn hàng được không ạ?"},{t:"Thank you. I can see there was a problem at our warehouse.",v:"Cảm ơn anh. Em thấy có sự cố ở kho bên em."},{t:"We'll send it by express delivery today. You'll get it tomorrow.",v:"Hôm nay bên em gửi chuyển phát nhanh. Ngày mai anh sẽ nhận được."},{t:"I understand. We'll give you a ten percent discount on your next order.",v:"Em hiểu ạ. Bên em sẽ giảm mười phần trăm cho đơn hàng tiếp theo của anh."}],notes:[{h:"Xin lỗi trước, giải thích sau",b:"Với khách đang bực, luôn mở đầu bằng \"I'm very sorry about that\", rồi mới hỏi thông tin và giải thích."},{h:"Đưa giải pháp cụ thể",b:"Nói rõ hành động và thời gian: \"We'll send it... today. You'll get it tomorrow.\""}]},
 {id:"en-w-mkt-idea",title:"Họp lên ý tưởng chiến dịch",scene:"Nhóm marketing họp lên ý tưởng cho dòng trà sữa mới.",partner:"Trưởng nhóm",ind:"mkt",work:true,lines:[{r:"A",t:"We're launching a new milk tea next month. Any ideas?",v:"Tháng sau mình ra mắt trà sữa mới. Mọi người có ý tưởng gì không?"},{r:"B",t:"Our target customers are students, so let's focus on TikTok.",v:"Khách hàng mục tiêu là sinh viên, nên mình tập trung vào TikTok đi."},{r:"A",t:"Good point. What kind of content?",v:"Ý hay. Nội dung kiểu gì?"},{r:"B",t:"Short videos with a fun challenge. People film themselves trying the drink.",v:"Video ngắn kèm một thử thách vui. Mọi người tự quay lúc thử đồ uống."},{r:"A",t:"I like it. What about a budget?",v:"Tôi thích đấy. Còn ngân sách?"},{r:"B",t:"I think we need about five thousand dollars for ads and influencers.",v:"Em nghĩ cần khoảng năm nghìn đô cho quảng cáo và người ảnh hưởng."},{r:"A",t:"How will we measure success?",v:"Mình đo hiệu quả thế nào?"},{r:"B",t:"By views, shares and the number of new customers in the first month.",v:"Bằng lượt xem, lượt chia sẻ và số khách hàng mới trong tháng đầu."},{r:"A",t:"Great. Can you write a short plan by Friday?",v:"Tuyệt. Em viết bản kế hoạch ngắn trước thứ Sáu nhé?"}],phrases:[{t:"Our target customers are students, so let's focus on TikTok.",v:"Khách hàng mục tiêu là sinh viên, nên mình tập trung vào TikTok đi."},{t:"Short videos with a fun challenge. People film themselves trying the drink.",v:"Video ngắn kèm một thử thách vui. Mọi người tự quay lúc thử đồ uống."},{t:"I think we need about five thousand dollars for ads and influencers.",v:"Em nghĩ cần khoảng năm nghìn đô cho quảng cáo và người ảnh hưởng."},{t:"By views, shares and the number of new customers in the first month.",v:"Bằng lượt xem, lượt chia sẻ và số khách hàng mới trong tháng đầu."}],notes:[{h:"let's + động từ để đề xuất",b:"\"Let's focus on TikTok\" là cách rủ cả nhóm làm gì. Lịch sự hơn: \"How about focusing on TikTok?\""},{h:"Good point",b:"\"Good point\" là \"ý hay\", dùng để ghi nhận ý kiến người khác trong cuộc họp."}]},
 {id:"en-w-mkt-result",title:"Báo cáo kết quả quảng cáo",scene:"Bạn báo cáo kết quả chiến dịch quảng cáo trên mạng xã hội.",partner:"Quản lý",ind:"mkt",work:true,lines:[{r:"A",t:"How did the Facebook ads perform last month?",v:"Quảng cáo Facebook tháng trước hiệu quả thế nào?"},{r:"B",t:"We reached two hundred thousand people, and the click-through rate was three percent.",v:"Mình tiếp cận hai trăm nghìn người, tỷ lệ nhấp là ba phần trăm."},{r:"A",t:"Is that good?",v:"Như vậy có tốt không?"},{r:"B",t:"Yes, it's higher than the industry average of about one percent.",v:"Có ạ, cao hơn mức trung bình ngành khoảng một phần trăm."},{r:"A",t:"What about sales?",v:"Còn doanh số?"},{r:"B",t:"We got four hundred orders, and the cost per order was five dollars.",v:"Mình có bốn trăm đơn, chi phí mỗi đơn là năm đô."},{r:"A",t:"Which ad worked best?",v:"Mẫu quảng cáo nào hiệu quả nhất?"},{r:"B",t:"The video ads. I suggest we spend more on video next month.",v:"Quảng cáo video ạ. Em đề xuất tháng sau chi nhiều hơn cho video."},{r:"A",t:"Agreed. Let's do that.",v:"Đồng ý. Làm vậy đi."}],phrases:[{t:"We reached two hundred thousand people, and the click-through rate was three percent.",v:"Mình tiếp cận hai trăm nghìn người, tỷ lệ nhấp là ba phần trăm."},{t:"Yes, it's higher than the industry average of about one percent.",v:"Có ạ, cao hơn mức trung bình ngành khoảng một phần trăm."},{t:"We got four hundred orders, and the cost per order was five dollars.",v:"Mình có bốn trăm đơn, chi phí mỗi đơn là năm đô."},{t:"The video ads. I suggest we spend more on video next month.",v:"Quảng cáo video ạ. Em đề xuất tháng sau chi nhiều hơn cho video."}],notes:[{h:"So sánh với trung bình",b:"\"higher than the industry average\" giúp người nghe hiểu con số có ý nghĩa gì."},{h:"Kết thúc báo cáo bằng đề xuất",b:"Sau số liệu luôn có bước tiếp theo: \"I suggest we spend more on video.\""}]},
 {id:"en-w-mkt-partner",title:"Làm việc với đối tác truyền thông",scene:"Bạn liên hệ một người có ảnh hưởng để hợp tác quảng bá sản phẩm.",partner:"Người có ảnh hưởng",ind:"mkt",work:true,lines:[{r:"A",t:"Hi, I got your email about working together.",v:"Chào bạn, tôi đã nhận email về việc hợp tác."},{r:"B",t:"Thanks for replying! We love your videos about healthy food.",v:"Cảm ơn chị đã trả lời! Bên em rất thích video về đồ ăn lành mạnh của chị."},{r:"A",t:"Thank you. What do you have in mind?",v:"Cảm ơn. Bên bạn định làm gì?"},{r:"B",t:"We'd like you to make two videos about our new snack.",v:"Bên em muốn chị làm hai video về món ăn vặt mới."},{r:"A",t:"What's the deadline?",v:"Hạn chót là khi nào?"},{r:"B",t:"The first video by the fifteenth, and the second by the end of the month.",v:"Video đầu trước ngày mười lăm, video thứ hai trước cuối tháng."},{r:"A",t:"And my fee?",v:"Còn chi phí cho tôi?"},{r:"B",t:"We can pay one thousand dollars for both videos. Does that work for you?",v:"Bên em trả một nghìn đô cho cả hai video. Chị thấy được không ạ?"},{r:"A",t:"Sounds fair. Please send me the contract.",v:"Nghe hợp lý. Gửi tôi hợp đồng nhé."}],phrases:[{t:"Thanks for replying! We love your videos about healthy food.",v:"Cảm ơn chị đã trả lời! Bên em rất thích video về đồ ăn lành mạnh của chị."},{t:"We'd like you to make two videos about our new snack.",v:"Bên em muốn chị làm hai video về món ăn vặt mới."},{t:"The first video by the fifteenth, and the second by the end of the month.",v:"Video đầu trước ngày mười lăm, video thứ hai trước cuối tháng."},{t:"We can pay one thousand dollars for both videos. Does that work for you?",v:"Bên em trả một nghìn đô cho cả hai video. Chị thấy được không ạ?"}],notes:[{h:"Khen trước khi đề nghị",b:"Mở đầu bằng lời khen cụ thể (\"We love your videos about...\") cho thấy bạn đã tìm hiểu kỹ đối tác."},{h:"Does that work for you?",b:"Câu hỏi mềm mỏng để kiểm tra đối phương có đồng ý không, dùng nhiều trong công việc."}]},
 {id:"en-w-hr-interview",title:"Phỏng vấn ứng viên",scene:"Bạn là nhân viên nhân sự, phỏng vấn ứng viên cho vị trí kế toán.",partner:"Ứng viên",ind:"hr",work:true,lines:[{r:"A",t:"Good morning. I'm here for the interview.",v:"Chào buổi sáng. Tôi đến để phỏng vấn."},{r:"B",t:"Welcome. Please have a seat. Can you tell me about yourself?",v:"Chào mừng bạn. Mời ngồi. Bạn giới thiệu về bản thân nhé?"},{r:"A",t:"I graduated in finance two years ago, and I work at a bank now.",v:"Tôi tốt nghiệp ngành tài chính hai năm trước và hiện làm ở một ngân hàng."},{r:"B",t:"Why do you want to leave your current job?",v:"Vì sao bạn muốn rời công việc hiện tại?"},{r:"A",t:"I want to learn more about corporate accounting.",v:"Tôi muốn học thêm về kế toán doanh nghiệp."},{r:"B",t:"Can you give me an example of a problem you solved at work?",v:"Bạn kể một ví dụ về vấn đề bạn đã giải quyết trong công việc nhé?"},{r:"A",t:"I found an error in our reports and fixed the process.",v:"Tôi phát hiện lỗi trong báo cáo và sửa lại quy trình."},{r:"B",t:"Great. What salary are you expecting?",v:"Tốt lắm. Bạn mong muốn mức lương bao nhiêu?"},{r:"A",t:"Around fifteen million dong a month.",v:"Khoảng mười lăm triệu đồng một tháng."},{r:"B",t:"Thank you. We'll contact you within a week.",v:"Cảm ơn bạn. Chúng tôi sẽ liên hệ trong vòng một tuần."}],phrases:[{t:"Welcome. Please have a seat. Can you tell me about yourself?",v:"Chào mừng bạn. Mời ngồi. Bạn giới thiệu về bản thân nhé?"},{t:"Why do you want to leave your current job?",v:"Vì sao bạn muốn rời công việc hiện tại?"},{t:"Can you give me an example of a problem you solved at work?",v:"Bạn kể một ví dụ về vấn đề bạn đã giải quyết trong công việc nhé?"},{t:"Great. What salary are you expecting?",v:"Tốt lắm. Bạn mong muốn mức lương bao nhiêu?"}],notes:[{h:"Câu hỏi hành vi",b:"\"Can you give me an example of...\" là kiểu câu hỏi hành vi, rất phổ biến trong phỏng vấn tiếng Anh."},{h:"current và previous",b:"current job là công việc hiện tại, previous job là công việc trước đây."}]},
 {id:"en-w-hr-meeting",title:"Họp nhóm phân công việc",scene:"Bạn là trưởng nhóm, chia việc cho dự án mới.",partner:"Đồng nghiệp",ind:"hr",work:true,lines:[{r:"A",t:"So what are we working on this week?",v:"Tuần này mình làm gì đây?"},{r:"B",t:"We need to finish the customer survey by Friday.",v:"Mình cần hoàn thành khảo sát khách hàng trước thứ Sáu."},{r:"A",t:"What should I do?",v:"Tôi nên làm gì?"},{r:"B",t:"Could you design the questions? Mai will send the survey to customers.",v:"Anh thiết kế câu hỏi được không? Mai sẽ gửi khảo sát cho khách hàng."},{r:"A",t:"Sure. When do you need the questions?",v:"Được. Khi nào chị cần bộ câu hỏi?"},{r:"B",t:"By Wednesday, if possible. Then I'll review them.",v:"Trước thứ Tư nếu được. Sau đó tôi sẽ xem lại."},{r:"A",t:"What if I need help?",v:"Nếu tôi cần giúp thì sao?"},{r:"B",t:"Just let me know. Let's have a quick check-in on Thursday.",v:"Cứ báo tôi. Thứ Năm mình họp nhanh để cập nhật nhé."},{r:"A",t:"Sounds good.",v:"Được đấy."}],phrases:[{t:"We need to finish the customer survey by Friday.",v:"Mình cần hoàn thành khảo sát khách hàng trước thứ Sáu."},{t:"Could you design the questions? Mai will send the survey to customers.",v:"Anh thiết kế câu hỏi được không? Mai sẽ gửi khảo sát cho khách hàng."},{t:"By Wednesday, if possible. Then I'll review them.",v:"Trước thứ Tư nếu được. Sau đó tôi sẽ xem lại."},{t:"Just let me know. Let's have a quick check-in on Thursday.",v:"Cứ báo tôi. Thứ Năm mình họp nhanh để cập nhật nhé."}],notes:[{h:"Could you...? để giao việc",b:"Trưởng nhóm thường dùng \"Could you...?\" thay vì ra lệnh, giúp không khí làm việc dễ chịu."},{h:"if possible",b:"Thêm \"if possible\" để mềm câu yêu cầu về thời hạn."}]},
 {id:"en-w-hr-leave",title:"Xin nghỉ phép",scene:"Bạn xin quản lý nghỉ phép vài ngày.",partner:"Quản lý",ind:"hr",work:true,lines:[{r:"A",t:"Hi, do you have a minute?",v:"Chào em, em có chuyện gì không?"},{r:"B",t:"Yes. I'd like to take three days off next week.",v:"Vâng. Em muốn xin nghỉ ba ngày tuần sau ạ."},{r:"A",t:"Which days?",v:"Những ngày nào?"},{r:"B",t:"From Wednesday to Friday. My sister is getting married.",v:"Từ thứ Tư đến thứ Sáu ạ. Chị gái em lấy chồng."},{r:"A",t:"Congratulations! Who will cover your work?",v:"Chúc mừng! Ai sẽ làm thay việc của em?"},{r:"B",t:"Nam has agreed to handle my emails, and I'll finish the report before I leave.",v:"Nam đã đồng ý xử lý email giúp em, và em sẽ làm xong báo cáo trước khi nghỉ."},{r:"A",t:"Perfect. Please send the leave request in the system.",v:"Tốt lắm. Em gửi đơn nghỉ phép trên hệ thống nhé."},{r:"B",t:"I will. Thank you for understanding.",v:"Em sẽ gửi ạ. Cảm ơn anh đã thông cảm."}],phrases:[{t:"Yes. I'd like to take three days off next week.",v:"Vâng. Em muốn xin nghỉ ba ngày tuần sau ạ."},{t:"From Wednesday to Friday. My sister is getting married.",v:"Từ thứ Tư đến thứ Sáu ạ. Chị gái em lấy chồng."},{t:"Nam has agreed to handle my emails, and I'll finish the report before I leave.",v:"Nam đã đồng ý xử lý email giúp em, và em sẽ làm xong báo cáo trước khi nghỉ."},{t:"I will. Thank you for understanding.",v:"Em sẽ gửi ạ. Cảm ơn anh đã thông cảm."}],notes:[{h:"take ... days off",b:"\"Take three days off\" là nghỉ ba ngày. \"Day off\" là ngày nghỉ."},{h:"Chuẩn bị người làm thay",b:"Trước khi xin nghỉ, nói rõ ai làm thay (cover) và việc nào đã xong để quản lý yên tâm."}]},
 {id:"en-w-it-standup",title:"Họp nhanh đầu ngày",scene:"Nhóm phần mềm họp nhanh mỗi sáng. Bạn là lập trình viên.",partner:"Trưởng nhóm",ind:"it",work:true,lines:[{r:"A",t:"Good morning, everyone. Let's start the stand-up. Linh?",v:"Chào cả nhóm. Bắt đầu họp nhanh nhé. Linh?"},{r:"B",t:"Yesterday I finished the login page.",v:"Hôm qua em làm xong trang đăng nhập."},{r:"A",t:"Great. What are you doing today?",v:"Tốt. Hôm nay em làm gì?"},{r:"B",t:"Today I'm going to connect it to the database.",v:"Hôm nay em sẽ kết nối nó với cơ sở dữ liệu."},{r:"A",t:"Any blockers?",v:"Có gì đang vướng không?"},{r:"B",t:"Yes, I don't have access to the test server yet.",v:"Có ạ, em chưa có quyền truy cập máy chủ thử nghiệm."},{r:"A",t:"I'll ask the admin to give you access this morning.",v:"Sáng nay anh sẽ nhờ quản trị cấp quyền cho em."},{r:"B",t:"Thanks. Then I can deploy it to test by tomorrow.",v:"Cảm ơn anh. Vậy mai em có thể đưa lên môi trường thử."}],phrases:[{t:"Yesterday I finished the login page.",v:"Hôm qua em làm xong trang đăng nhập."},{t:"Today I'm going to connect it to the database.",v:"Hôm nay em sẽ kết nối nó với cơ sở dữ liệu."},{t:"Yes, I don't have access to the test server yet.",v:"Có ạ, em chưa có quyền truy cập máy chủ thử nghiệm."},{t:"Thanks. Then I can deploy it to test by tomorrow.",v:"Cảm ơn anh. Vậy mai em có thể đưa lên môi trường thử."}],notes:[{h:"Ba câu trong buổi họp nhanh",b:"Mỗi người trả lời: hôm qua làm gì (Yesterday I...), hôm nay làm gì (Today I'm going to...), có gì vướng (blockers)."},{h:"blocker",b:"\"Blocker\" là việc đang cản trở bạn làm tiếp. Nói rõ cần ai giúp gì."}]},
 {id:"en-w-it-support",title:"Hỗ trợ kỹ thuật",scene:"Một đồng nghiệp gọi vì không vào được email. Bạn ở bộ phận IT.",partner:"Đồng nghiệp",ind:"it",work:true,lines:[{r:"A",t:"Hi, I can't log in to my email.",v:"Chào anh, em không đăng nhập được email."},{r:"B",t:"OK. What error message do you see?",v:"Được. Em thấy thông báo lỗi gì?"},{r:"A",t:"It says my password is wrong.",v:"Nó báo mật khẩu sai."},{r:"B",t:"Did you change your password recently?",v:"Gần đây em có đổi mật khẩu không?"},{r:"A",t:"Yes, yesterday.",v:"Có ạ, hôm qua."},{r:"B",t:"Please restart your computer and try the new password again.",v:"Em khởi động lại máy rồi thử lại mật khẩu mới nhé."},{r:"A",t:"It still doesn't work.",v:"Vẫn không được ạ."},{r:"B",t:"OK, I'll reset it for you. Check your phone for a code.",v:"Được, anh sẽ đặt lại cho em. Em xem mã trên điện thoại nhé."},{r:"A",t:"Got it. It works now. Thank you!",v:"Có rồi. Giờ được rồi. Cảm ơn anh!"}],phrases:[{t:"OK. What error message do you see?",v:"Được. Em thấy thông báo lỗi gì?"},{t:"Did you change your password recently?",v:"Gần đây em có đổi mật khẩu không?"},{t:"Please restart your computer and try the new password again.",v:"Em khởi động lại máy rồi thử lại mật khẩu mới nhé."},{t:"OK, I'll reset it for you. Check your phone for a code.",v:"Được, anh sẽ đặt lại cho em. Em xem mã trên điện thoại nhé."}],notes:[{h:"Hỏi từng bước để tìm nguyên nhân",b:"Người hỗ trợ hỏi thông báo lỗi, rồi hỏi thay đổi gần đây. Đây là cách xử lý sự cố chuẩn."},{h:"It doesn't work",b:"\"It doesn't work\" là không chạy, không được. Câu này dùng rất nhiều khi báo lỗi."}]},
 {id:"en-w-it-require",title:"Trao đổi yêu cầu với khách hàng",scene:"Bạn là trưởng dự án, hỏi khách hàng về yêu cầu cho ứng dụng.",partner:"Khách hàng",ind:"it",work:true,lines:[{r:"A",t:"We want an app for our customers to book appointments.",v:"Chúng tôi muốn có ứng dụng để khách đặt lịch hẹn."},{r:"B",t:"Sure. Who will use the app, and on which devices?",v:"Vâng. Ai sẽ dùng ứng dụng, và trên thiết bị nào ạ?"},{r:"A",t:"Our customers, mostly on their phones.",v:"Khách hàng của chúng tôi, chủ yếu trên điện thoại."},{r:"B",t:"Do you need online payment in the app?",v:"Anh có cần thanh toán trực tuyến trong ứng dụng không?"},{r:"A",t:"Yes, but that can come later.",v:"Có, nhưng để sau cũng được."},{r:"B",t:"OK. So for version one, we'll focus on booking and reminders.",v:"Vâng. Vậy phiên bản đầu, bên em tập trung vào đặt lịch và nhắc lịch."},{r:"A",t:"How long will it take?",v:"Mất bao lâu?"},{r:"B",t:"About three months. I'll send you a timeline and a quote this week.",v:"Khoảng ba tháng. Tuần này em gửi anh lịch trình và báo giá."}],phrases:[{t:"Sure. Who will use the app, and on which devices?",v:"Vâng. Ai sẽ dùng ứng dụng, và trên thiết bị nào ạ?"},{t:"Do you need online payment in the app?",v:"Anh có cần thanh toán trực tuyến trong ứng dụng không?"},{t:"OK. So for version one, we'll focus on booking and reminders.",v:"Vâng. Vậy phiên bản đầu, bên em tập trung vào đặt lịch và nhắc lịch."},{t:"About three months. I'll send you a timeline and a quote this week.",v:"Khoảng ba tháng. Tuần này em gửi anh lịch trình và báo giá."}],notes:[{h:"Hỏi ai và thiết bị nào",b:"Trước khi làm phần mềm, luôn hỏi người dùng là ai (users) và dùng trên thiết bị nào (devices)."},{h:"version one",b:"Chia yêu cầu thành các phiên bản: phiên bản đầu (version one) chỉ làm phần quan trọng nhất."}]},
 {id:"en-w-hosp-checkin",title:"Lễ tân nhận phòng",scene:"Bạn là lễ tân khách sạn, làm thủ tục nhận phòng cho khách.",partner:"Khách",ind:"hosp",work:true,lines:[{r:"A",t:"Hi, I have a reservation under the name Smith.",v:"Chào bạn, tôi đặt phòng tên Smith."},{r:"B",t:"Welcome! May I see your passport, please?",v:"Chào mừng anh! Cho em xem hộ chiếu được không ạ?"},{r:"A",t:"Here you are.",v:"Đây."},{r:"B",t:"Thank you. You're staying for three nights in a double room.",v:"Cảm ơn anh. Anh ở ba đêm, phòng đôi."},{r:"A",t:"That's right. What time is breakfast?",v:"Đúng rồi. Bữa sáng lúc mấy giờ?"},{r:"B",t:"Breakfast is from six thirty to ten on the second floor.",v:"Bữa sáng từ sáu rưỡi đến mười giờ ở tầng hai."},{r:"A",t:"Great. And the Wi-Fi password?",v:"Tốt. Còn mật khẩu Wi-Fi?"},{r:"B",t:"It's on your key card. Your room is 512. Enjoy your stay!",v:"Mật khẩu ở trên thẻ phòng. Phòng của anh là 512. Chúc anh nghỉ ngơi vui vẻ!"}],phrases:[{t:"Welcome! May I see your passport, please?",v:"Chào mừng anh! Cho em xem hộ chiếu được không ạ?"},{t:"Thank you. You're staying for three nights in a double room.",v:"Cảm ơn anh. Anh ở ba đêm, phòng đôi."},{t:"Breakfast is from six thirty to ten on the second floor.",v:"Bữa sáng từ sáu rưỡi đến mười giờ ở tầng hai."},{t:"It's on your key card. Your room is 512. Enjoy your stay!",v:"Mật khẩu ở trên thẻ phòng. Phòng của anh là 512. Chúc anh nghỉ ngơi vui vẻ!"}],notes:[{h:"May I...? lịch sự với khách",b:"Nhân viên khách sạn dùng \"May I see...?\" thay cho \"Give me...\" để lịch sự."},{h:"Đọc số phòng",b:"512 thường đọc là \"five one two\" hoặc \"five twelve\"."}]},
 {id:"en-w-hosp-order",title:"Phục vụ gọi món",scene:"Bạn là phục vụ nhà hàng, nhận gọi món từ khách.",partner:"Khách",ind:"hosp",work:true,lines:[{r:"A",t:"Hi, can we see the menu?",v:"Chào em, cho chị xem thực đơn."},{r:"B",t:"Of course. Here you are. Can I get you something to drink first?",v:"Vâng ạ. Đây ạ. Chị gọi đồ uống trước không ạ?"},{r:"A",t:"Two iced teas, please. What do you recommend?",v:"Cho hai trà đá. Em gợi ý món gì?"},{r:"B",t:"Our grilled fish is very popular. It comes with rice and salad.",v:"Cá nướng bên em rất được ưa chuộng. Ăn kèm cơm và salad."},{r:"A",t:"Is it spicy?",v:"Có cay không?"},{r:"B",t:"Just a little. We can make it not spicy if you like.",v:"Chỉ hơi cay thôi ạ. Nếu chị muốn bên em làm không cay."},{r:"A",t:"Not spicy, please. And one beef noodle soup.",v:"Không cay nhé. Thêm một phở bò."},{r:"B",t:"So, one grilled fish, not spicy, one beef noodle soup and two iced teas.",v:"Vậy là một cá nướng không cay, một phở bò và hai trà đá."},{r:"A",t:"That's right.",v:"Đúng rồi."}],phrases:[{t:"Of course. Here you are. Can I get you something to drink first?",v:"Vâng ạ. Đây ạ. Chị gọi đồ uống trước không ạ?"},{t:"Our grilled fish is very popular. It comes with rice and salad.",v:"Cá nướng bên em rất được ưa chuộng. Ăn kèm cơm và salad."},{t:"Just a little. We can make it not spicy if you like.",v:"Chỉ hơi cay thôi ạ. Nếu chị muốn bên em làm không cay."},{t:"So, one grilled fish, not spicy, one beef noodle soup and two iced teas.",v:"Vậy là một cá nướng không cay, một phở bò và hai trà đá."}],notes:[{h:"Can I get you...?",b:"\"Can I get you something to drink?\" là câu mời gọi món tự nhiên của phục vụ."},{h:"Nhắc lại đơn hàng",b:"Phục vụ luôn đọc lại đơn (\"So, one... and...\") để tránh sai sót."}]},
 {id:"en-w-hosp-tour",title:"Hướng dẫn viên du lịch",scene:"Bạn là hướng dẫn viên, giới thiệu lịch trình tour phố cổ.",partner:"Khách du lịch",ind:"hosp",work:true,lines:[{r:"A",t:"Good morning! What's the plan for today?",v:"Chào buổi sáng! Kế hoạch hôm nay thế nào?"},{r:"B",t:"Good morning! Today we'll walk around the Old Quarter for about three hours.",v:"Chào buổi sáng! Hôm nay mình sẽ đi bộ quanh phố cổ khoảng ba tiếng."},{r:"A",t:"What will we see?",v:"Chúng ta sẽ xem gì?"},{r:"B",t:"First, Hoan Kiem Lake, then an old temple and a local market.",v:"Đầu tiên là hồ Hoàn Kiếm, sau đó là một ngôi đền cổ và một khu chợ địa phương."},{r:"A",t:"Can we try some street food?",v:"Mình có được ăn thử đồ ăn đường phố không?"},{r:"B",t:"Yes! We'll stop for egg coffee and spring rolls.",v:"Có ạ! Mình sẽ dừng lại uống cà phê trứng và ăn nem."},{r:"A",t:"Is it safe to cross the road here?",v:"Qua đường ở đây có an toàn không?"},{r:"B",t:"Walk slowly and don't stop. The motorbikes will go around you.",v:"Cứ đi chậm và đừng dừng lại. Xe máy sẽ đi vòng qua."},{r:"A",t:"Good tip! Let's go.",v:"Mẹo hay đấy! Đi thôi."}],phrases:[{t:"Good morning! Today we'll walk around the Old Quarter for about three hours.",v:"Chào buổi sáng! Hôm nay mình sẽ đi bộ quanh phố cổ khoảng ba tiếng."},{t:"First, Hoan Kiem Lake, then an old temple and a local market.",v:"Đầu tiên là hồ Hoàn Kiếm, sau đó là một ngôi đền cổ và một khu chợ địa phương."},{t:"Yes! We'll stop for egg coffee and spring rolls.",v:"Có ạ! Mình sẽ dừng lại uống cà phê trứng và ăn nem."},{t:"Walk slowly and don't stop. The motorbikes will go around you.",v:"Cứ đi chậm và đừng dừng lại. Xe máy sẽ đi vòng qua."}],notes:[{h:"First, then, after that",b:"Dùng các từ nối thứ tự để giới thiệu lịch trình rõ ràng."},{h:"Lời khuyên an toàn",b:"Hướng dẫn viên cần đưa lời khuyên ngắn gọn bằng câu mệnh lệnh: \"Walk slowly and don't stop.\""}]},
 {id:"en-w-med-nurse",title:"Tiếp nhận bệnh nhân",scene:"Bạn là điều dưỡng, hỏi thông tin bệnh nhân mới đến.",partner:"Bệnh nhân",ind:"med",work:true,lines:[{r:"A",t:"Hello, I have an appointment with Dr. Brown.",v:"Xin chào, tôi có hẹn với bác sĩ Brown."},{r:"B",t:"Welcome. Can I have your full name and date of birth?",v:"Chào anh. Cho tôi xin họ tên và ngày sinh ạ?"},{r:"A",t:"David Lee, May third, nineteen ninety.",v:"David Lee, ngày ba tháng Năm năm 1990."},{r:"B",t:"Thank you. What brings you in today?",v:"Cảm ơn anh. Hôm nay anh đến khám vì sao?"},{r:"A",t:"I've had a bad cough for a week.",v:"Tôi bị ho nặng một tuần nay."},{r:"B",t:"Do you have any allergies to medicine?",v:"Anh có dị ứng với thuốc nào không?"},{r:"A",t:"Yes, I'm allergic to penicillin.",v:"Có, tôi dị ứng penicillin."},{r:"B",t:"OK, I'll note that. Let me check your temperature and blood pressure.",v:"Vâng, tôi sẽ ghi lại. Để tôi đo nhiệt độ và huyết áp cho anh."}],phrases:[{t:"Welcome. Can I have your full name and date of birth?",v:"Chào anh. Cho tôi xin họ tên và ngày sinh ạ?"},{t:"Thank you. What brings you in today?",v:"Cảm ơn anh. Hôm nay anh đến khám vì sao?"},{t:"Do you have any allergies to medicine?",v:"Anh có dị ứng với thuốc nào không?"},{t:"OK, I'll note that. Let me check your temperature and blood pressure.",v:"Vâng, tôi sẽ ghi lại. Để tôi đo nhiệt độ và huyết áp cho anh."}],notes:[{h:"What brings you in today?",b:"Câu hỏi lịch sự, tự nhiên để hỏi lý do đến khám, thay cho \"What's wrong with you?\" nghe khá cộc."},{h:"Luôn hỏi dị ứng",b:"\"Do you have any allergies?\" là câu bắt buộc trước khi dùng thuốc."}]},
 {id:"en-w-med-doctor",title:"Bác sĩ khám và dặn dò",scene:"Bạn là bác sĩ, khám và dặn dò bệnh nhân bị viêm họng.",partner:"Bệnh nhân",ind:"med",work:true,lines:[{r:"A",t:"My throat really hurts, doctor.",v:"Bác sĩ ơi, tôi đau họng lắm."},{r:"B",t:"Let me have a look. Open your mouth and say \"ah\".",v:"Để tôi xem. Há miệng và nói \"a\"."},{r:"A",t:"Ah.",v:"A."},{r:"B",t:"Your throat is red and swollen. You have a throat infection.",v:"Họng anh đỏ và sưng. Anh bị viêm họng."},{r:"A",t:"Is it serious?",v:"Có nghiêm trọng không?"},{r:"B",t:"No, it's not serious. I'll give you some antibiotics.",v:"Không nghiêm trọng đâu. Tôi sẽ kê kháng sinh cho anh."},{r:"A",t:"How should I take them?",v:"Tôi uống thế nào?"},{r:"B",t:"One tablet three times a day after meals, for seven days.",v:"Một viên, ngày ba lần sau ăn, trong bảy ngày."},{r:"A",t:"Thank you, doctor.",v:"Cảm ơn bác sĩ."},{r:"B",t:"Drink plenty of water and come back if you don't feel better in three days.",v:"Uống nhiều nước và quay lại nếu ba ngày không đỡ."}],phrases:[{t:"Let me have a look. Open your mouth and say \"ah\".",v:"Để tôi xem. Há miệng và nói \"a\"."},{t:"Your throat is red and swollen. You have a throat infection.",v:"Họng anh đỏ và sưng. Anh bị viêm họng."},{t:"One tablet three times a day after meals, for seven days.",v:"Một viên, ngày ba lần sau ăn, trong bảy ngày."},{t:"Drink plenty of water and come back if you don't feel better in three days.",v:"Uống nhiều nước và quay lại nếu ba ngày không đỡ."}],notes:[{h:"Giải thích bằng câu ngắn, dễ hiểu",b:"Bác sĩ dùng từ đơn giản: \"It's not serious\" giúp bệnh nhân yên tâm."},{h:"Dặn uống thuốc",b:"Cấu trúc: số lượng + số lần + thời điểm + thời gian: \"One tablet three times a day after meals, for seven days.\""}]},
 {id:"en-w-med-pharmacy",title:"Tư vấn tại nhà thuốc",scene:"Bạn là dược sĩ, tư vấn thuốc cho khách bị cảm.",partner:"Khách",ind:"med",work:true,lines:[{r:"A",t:"Hi, I have a cold. What can I take?",v:"Chào chị, tôi bị cảm. Tôi uống gì được?"},{r:"B",t:"Do you have a fever or a sore throat?",v:"Anh có sốt hay đau họng không?"},{r:"A",t:"A sore throat and a runny nose, but no fever.",v:"Đau họng và sổ mũi, nhưng không sốt."},{r:"B",t:"I recommend these lozenges and this cold medicine.",v:"Tôi gợi ý viên ngậm này và thuốc cảm này."},{r:"A",t:"Will it make me sleepy?",v:"Thuốc có gây buồn ngủ không?"},{r:"B",t:"Yes, it may. Don't drive after you take it.",v:"Có thể có. Đừng lái xe sau khi uống."},{r:"A",t:"How many can I take a day?",v:"Một ngày tôi uống được mấy viên?"},{r:"B",t:"No more than four tablets a day. If it gets worse, please see a doctor.",v:"Không quá bốn viên một ngày. Nếu nặng hơn, anh nên đi khám bác sĩ."},{r:"A",t:"Thanks. How much is it?",v:"Cảm ơn. Bao nhiêu tiền?"}],phrases:[{t:"Do you have a fever or a sore throat?",v:"Anh có sốt hay đau họng không?"},{t:"I recommend these lozenges and this cold medicine.",v:"Tôi gợi ý viên ngậm này và thuốc cảm này."},{t:"Yes, it may. Don't drive after you take it.",v:"Có thể có. Đừng lái xe sau khi uống."},{t:"No more than four tablets a day. If it gets worse, please see a doctor.",v:"Không quá bốn viên một ngày. Nếu nặng hơn, anh nên đi khám bác sĩ."}],notes:[{h:"Cảnh báo tác dụng phụ",b:"\"It may make you sleepy. Don't drive\" là lời dặn bắt buộc với thuốc gây buồn ngủ."},{h:"No more than",b:"\"No more than four tablets a day\" là không quá bốn viên một ngày, cách nói liều tối đa."}]},
 {id:"en-w-ins-sell",title:"Tư vấn bảo hiểm sức khỏe",scene:"Một khách hàng muốn mua bảo hiểm sức khỏe cho gia đình. Bạn là tư vấn viên.",partner:"Khách hàng",ind:"ins",work:true,lines:[{r:"A",t:"I'm looking for health insurance for my family.",v:"Tôi đang tìm bảo hiểm sức khỏe cho gia đình."},{r:"B",t:"Sure. How many people would you like to cover?",v:"Vâng. Anh muốn bảo hiểm cho mấy người ạ?"},{r:"A",t:"Four. My wife, two kids and me.",v:"Bốn người. Vợ tôi, hai con và tôi."},{r:"B",t:"Our family plan covers hospital stays, surgery and doctor visits.",v:"Gói gia đình bên em chi trả nằm viện, phẫu thuật và khám bác sĩ."},{r:"A",t:"How much is the premium?",v:"Phí bảo hiểm là bao nhiêu?"},{r:"B",t:"It's about two hundred dollars a month for four people.",v:"Khoảng hai trăm đô một tháng cho bốn người."},{r:"A",t:"Is there a waiting period?",v:"Có thời gian chờ không?"},{r:"B",t:"Yes, thirty days for illness, but accidents are covered from the first day.",v:"Có ạ, ba mươi ngày với bệnh, còn tai nạn được chi trả ngay từ ngày đầu."},{r:"A",t:"OK. Can I read the policy first?",v:"Được. Tôi đọc hợp đồng trước được không?"},{r:"B",t:"Of course. I'll email you the full policy today.",v:"Tất nhiên. Hôm nay em gửi email hợp đồng đầy đủ cho anh."}],phrases:[{t:"Sure. How many people would you like to cover?",v:"Vâng. Anh muốn bảo hiểm cho mấy người ạ?"},{t:"Our family plan covers hospital stays, surgery and doctor visits.",v:"Gói gia đình bên em chi trả nằm viện, phẫu thuật và khám bác sĩ."},{t:"It's about two hundred dollars a month for four people.",v:"Khoảng hai trăm đô một tháng cho bốn người."},{t:"Yes, thirty days for illness, but accidents are covered from the first day.",v:"Có ạ, ba mươi ngày với bệnh, còn tai nạn được chi trả ngay từ ngày đầu."}],notes:[{h:"cover nghĩa là \"chi trả, bảo vệ\"",b:"\"The plan covers surgery\" là gói bảo hiểm chi trả phẫu thuật. Danh từ là coverage (phạm vi bảo hiểm)."},{h:"premium không phải \"cao cấp\"",b:"Trong bảo hiểm, premium là phí bảo hiểm phải đóng định kỳ."}]},
 {id:"en-w-ins-claim",title:"Hướng dẫn làm hồ sơ bồi thường",scene:"Khách hàng gọi để yêu cầu bồi thường sau khi nằm viện.",partner:"Khách hàng",ind:"ins",work:true,lines:[{r:"A",t:"Hi, I was in hospital last week. How do I make a claim?",v:"Chào chị, tuần trước tôi nằm viện. Tôi yêu cầu bồi thường thế nào?"},{r:"B",t:"I'm sorry to hear that. Can I have your policy number?",v:"Tôi rất tiếc. Anh cho tôi số hợp đồng được không?"},{r:"A",t:"It's H-two-zero-five-eight.",v:"Số H2058."},{r:"B",t:"Thank you. Please send us the hospital bill and the medical report.",v:"Cảm ơn anh. Anh gửi cho bên tôi hóa đơn viện phí và giấy ra viện nhé."},{r:"A",t:"Can I send them online?",v:"Tôi gửi trực tuyến được không?"},{r:"B",t:"Yes, just upload photos in our app under \"Claims\".",v:"Được ạ, anh chỉ cần tải ảnh lên ứng dụng ở mục \"Bồi thường\"."},{r:"A",t:"How long does it take?",v:"Mất bao lâu?"},{r:"B",t:"Usually ten working days. We'll pay the money into your bank account.",v:"Thường là mười ngày làm việc. Bên tôi sẽ chuyển tiền vào tài khoản ngân hàng của anh."}],phrases:[{t:"I'm sorry to hear that. Can I have your policy number?",v:"Tôi rất tiếc. Anh cho tôi số hợp đồng được không?"},{t:"Thank you. Please send us the hospital bill and the medical report.",v:"Cảm ơn anh. Anh gửi cho bên tôi hóa đơn viện phí và giấy ra viện nhé."},{t:"Yes, just upload photos in our app under \"Claims\".",v:"Được ạ, anh chỉ cần tải ảnh lên ứng dụng ở mục \"Bồi thường\"."},{t:"Usually ten working days. We'll pay the money into your bank account.",v:"Thường là mười ngày làm việc. Bên tôi sẽ chuyển tiền vào tài khoản ngân hàng của anh."}],notes:[{h:"make a claim",b:"\"Make a claim\" là yêu cầu bồi thường. Người yêu cầu gọi là claimant."},{h:"working days",b:"\"Ten working days\" là mười ngày làm việc, không tính thứ Bảy, Chủ nhật và ngày lễ."}]},
 {id:"en-w-ins-car",title:"Bảo hiểm xe sau tai nạn",scene:"Khách hàng báo bị va chạm xe. Bạn là nhân viên giám định.",partner:"Khách hàng",ind:"ins",work:true,lines:[{r:"A",t:"Someone hit my car this morning.",v:"Sáng nay có người đâm vào xe tôi."},{r:"B",t:"Are you OK? Was anyone hurt?",v:"Anh có sao không? Có ai bị thương không?"},{r:"A",t:"No, I'm fine. But the back of the car is damaged.",v:"Không, tôi ổn. Nhưng đuôi xe bị hỏng."},{r:"B",t:"Did you take photos and get the other driver's details?",v:"Anh có chụp ảnh và lấy thông tin người lái xe kia không?"},{r:"A",t:"Yes, I have his name, phone number and plate number.",v:"Có, tôi có tên, số điện thoại và biển số xe của anh ta."},{r:"B",t:"Good. Please bring the car to one of our partner garages.",v:"Tốt. Anh mang xe đến một gara đối tác của bên tôi nhé."},{r:"A",t:"Will I have to pay anything?",v:"Tôi có phải trả gì không?"},{r:"B",t:"If it wasn't your fault, the other driver's insurance will pay for the repair.",v:"Nếu không phải lỗi của anh, bảo hiểm của người lái kia sẽ trả tiền sửa."}],phrases:[{t:"Are you OK? Was anyone hurt?",v:"Anh có sao không? Có ai bị thương không?"},{t:"Did you take photos and get the other driver's details?",v:"Anh có chụp ảnh và lấy thông tin người lái xe kia không?"},{t:"Good. Please bring the car to one of our partner garages.",v:"Tốt. Anh mang xe đến một gara đối tác của bên tôi nhé."},{t:"If it wasn't your fault, the other driver's insurance will pay for the repair.",v:"Nếu không phải lỗi của anh, bảo hiểm của người lái kia sẽ trả tiền sửa."}],notes:[{h:"Hỏi thăm trước khi hỏi giấy tờ",b:"\"Are you OK? Was anyone hurt?\" thể hiện sự quan tâm, rất quan trọng khi khách vừa gặp sự cố."},{h:"fault",b:"\"It wasn't your fault\" là không phải lỗi của bạn. \"At fault\" là người có lỗi."}]},
 {id:"en-w-log-ship",title:"Đặt lịch vận chuyển hàng",scene:"Bạn liên hệ công ty vận tải để gửi một lô hàng sang Úc.",partner:"Công ty vận tải",ind:"log",work:true,lines:[{r:"A",t:"Good morning, Global Freight. How can I help?",v:"Chào buổi sáng, Global Freight xin nghe. Tôi giúp gì được ạ?"},{r:"B",t:"Hi, I'd like to ship two containers of furniture to Sydney.",v:"Chào chị, tôi muốn gửi hai container đồ nội thất sang Sydney."},{r:"A",t:"Sure. Forty-foot containers?",v:"Vâng. Container bốn mươi feet ạ?"},{r:"B",t:"Yes. When is the next ship from Hai Phong?",v:"Đúng. Chuyến tàu tiếp theo từ Hải Phòng là khi nào?"},{r:"A",t:"There's one on the twelfth. It arrives in about eighteen days.",v:"Có chuyến ngày mười hai. Khoảng mười tám ngày thì đến."},{r:"B",t:"Great. What's the total cost, including port fees?",v:"Tốt. Tổng chi phí bao gồm cả phí cảng là bao nhiêu?"},{r:"A",t:"About three thousand dollars per container. I'll send you a quote.",v:"Khoảng ba nghìn đô mỗi container. Tôi sẽ gửi báo giá."},{r:"B",t:"Thanks. Please also tell me which documents you need.",v:"Cảm ơn. Chị cho tôi biết cần những chứng từ gì nhé."}],phrases:[{t:"Hi, I'd like to ship two containers of furniture to Sydney.",v:"Chào chị, tôi muốn gửi hai container đồ nội thất sang Sydney."},{t:"Yes. When is the next ship from Hai Phong?",v:"Đúng. Chuyến tàu tiếp theo từ Hải Phòng là khi nào?"},{t:"Great. What's the total cost, including port fees?",v:"Tốt. Tổng chi phí bao gồm cả phí cảng là bao nhiêu?"},{t:"Thanks. Please also tell me which documents you need.",v:"Cảm ơn. Chị cho tôi biết cần những chứng từ gì nhé."}],notes:[{h:"ship vừa là \"tàu\" vừa là \"gửi hàng\"",b:"\"Ship\" động từ là vận chuyển, gửi hàng. Shipment là lô hàng, shipping là việc vận chuyển."},{h:"including",b:"\"Including port fees\" là bao gồm phí cảng. Ngược lại: excluding (không bao gồm)."}]},
 {id:"en-w-log-customs",title:"Làm thủ tục hải quan",scene:"Lô hàng nhập khẩu bị giữ ở hải quan. Bạn gọi cho nhân viên đại lý hải quan.",partner:"Đại lý hải quan",ind:"log",work:true,lines:[{r:"A",t:"Hello, your shipment is being held at customs.",v:"Chào anh, lô hàng của anh đang bị giữ ở hải quan."},{r:"B",t:"Oh no. What's the problem?",v:"Ôi. Có vấn đề gì vậy?"},{r:"A",t:"The invoice value doesn't match the packing list.",v:"Giá trị trên hóa đơn không khớp với phiếu đóng gói."},{r:"B",t:"I see. I'll ask the supplier to send a corrected invoice today.",v:"Tôi hiểu rồi. Tôi sẽ nhờ nhà cung cấp gửi hóa đơn đã sửa ngay hôm nay."},{r:"A",t:"Good. You'll also need the certificate of origin.",v:"Tốt. Anh cũng cần giấy chứng nhận xuất xứ."},{r:"B",t:"We have that. How much is the import duty?",v:"Bên tôi có rồi. Thuế nhập khẩu là bao nhiêu?"},{r:"A",t:"Five percent, plus ten percent VAT.",v:"Năm phần trăm, cộng mười phần trăm thuế giá trị gia tăng."},{r:"B",t:"OK. When can we get the goods?",v:"Được. Khi nào bên tôi nhận được hàng?"},{r:"A",t:"Two days after we receive the new invoice.",v:"Hai ngày sau khi bên tôi nhận hóa đơn mới."}],phrases:[{t:"Oh no. What's the problem?",v:"Ôi. Có vấn đề gì vậy?"},{t:"I see. I'll ask the supplier to send a corrected invoice today.",v:"Tôi hiểu rồi. Tôi sẽ nhờ nhà cung cấp gửi hóa đơn đã sửa ngay hôm nay."},{t:"We have that. How much is the import duty?",v:"Bên tôi có rồi. Thuế nhập khẩu là bao nhiêu?"},{t:"OK. When can we get the goods?",v:"Được. Khi nào bên tôi nhận được hàng?"}],notes:[{h:"be being held",b:"\"Is being held\" là đang bị giữ (bị động tiếp diễn). Dùng khi việc đang xảy ra."},{h:"match",b:"\"Doesn't match\" là không khớp. Hải quan rất hay kiểm tra số liệu có khớp giữa các chứng từ không."}]},
 {id:"en-w-log-warehouse",title:"Quản lý kho hàng",scene:"Bạn là quản lý kho, trao đổi với nhân viên về đơn hàng cần xuất.",partner:"Nhân viên kho",ind:"log",work:true,lines:[{r:"A",t:"We have fifty orders to ship today.",v:"Hôm nay mình có năm mươi đơn cần giao."},{r:"B",t:"OK. Let's pick the urgent orders first.",v:"Được. Mình lấy hàng các đơn gấp trước."},{r:"A",t:"Some items are out of stock.",v:"Một số mặt hàng hết hàng rồi."},{r:"B",t:"Check the system and tell me which ones.",v:"Kiểm tra hệ thống rồi báo tôi là mặt hàng nào."},{r:"A",t:"The blue T-shirts in size M.",v:"Áo phông xanh cỡ M."},{r:"B",t:"We'll get more on Thursday. Please email those customers about the delay.",v:"Thứ Năm có hàng thêm. Em gửi email báo chậm cho các khách đó nhé."},{r:"A",t:"Sure. Should I print the shipping labels now?",v:"Vâng. Em in nhãn vận chuyển luôn nhé?"},{r:"B",t:"Yes, and double-check every address before packing.",v:"Có, và kiểm tra kỹ từng địa chỉ trước khi đóng gói."}],phrases:[{t:"OK. Let's pick the urgent orders first.",v:"Được. Mình lấy hàng các đơn gấp trước."},{t:"Check the system and tell me which ones.",v:"Kiểm tra hệ thống rồi báo tôi là mặt hàng nào."},{t:"We'll get more on Thursday. Please email those customers about the delay.",v:"Thứ Năm có hàng thêm. Em gửi email báo chậm cho các khách đó nhé."},{t:"Yes, and double-check every address before packing.",v:"Có, và kiểm tra kỹ từng địa chỉ trước khi đóng gói."}],notes:[{h:"out of stock / in stock",b:"out of stock là hết hàng, in stock là còn hàng. Restock là nhập lại hàng."},{h:"double-check",b:"\"Double-check\" là kiểm tra lại cho chắc, dùng rất nhiều trong công việc."}]},
 {id:"en-w-ecom-listing",title:"Đăng sản phẩm lên sàn",scene:"Bạn hướng dẫn nhân viên mới đăng sản phẩm lên sàn thương mại điện tử.",partner:"Nhân viên mới",ind:"ecom",work:true,lines:[{r:"A",t:"How do I add a new product to our shop?",v:"Em thêm sản phẩm mới vào gian hàng thế nào ạ?"},{r:"B",t:"First, upload at least five clear photos with a white background.",v:"Đầu tiên, tải lên ít nhất năm ảnh rõ nét có nền trắng."},{r:"A",t:"What about the title?",v:"Còn tiêu đề thì sao?"},{r:"B",t:"Put the main keyword first, like \"Women's running shoes\".",v:"Đặt từ khóa chính lên đầu, ví dụ \"Giày chạy bộ nữ\"."},{r:"A",t:"Should I write a long description?",v:"Em có nên viết mô tả dài không?"},{r:"B",t:"Keep it short. List the size, material and how to use it.",v:"Viết ngắn thôi. Ghi kích cỡ, chất liệu và cách sử dụng."},{r:"A",t:"And the price?",v:"Còn giá?"},{r:"B",t:"Check our competitors first, then set a slightly lower price for launch week.",v:"Xem giá đối thủ trước, rồi đặt giá thấp hơn một chút trong tuần ra mắt."}],phrases:[{t:"First, upload at least five clear photos with a white background.",v:"Đầu tiên, tải lên ít nhất năm ảnh rõ nét có nền trắng."},{t:"Put the main keyword first, like \"Women's running shoes\".",v:"Đặt từ khóa chính lên đầu, ví dụ \"Giày chạy bộ nữ\"."},{t:"Keep it short. List the size, material and how to use it.",v:"Viết ngắn thôi. Ghi kích cỡ, chất liệu và cách sử dụng."},{t:"Check our competitors first, then set a slightly lower price for launch week.",v:"Xem giá đối thủ trước, rồi đặt giá thấp hơn một chút trong tuần ra mắt."}],notes:[{h:"keyword",b:"Từ khóa (keyword) là từ khách gõ để tìm sản phẩm. Đặt ở đầu tiêu đề giúp sản phẩm dễ được tìm thấy."},{h:"Keep it short",b:"\"Keep it short\" là viết ngắn gọn. Cấu trúc keep + tính từ: keep it simple, keep it clean."}]},
 {id:"en-w-ecom-chat",title:"Chăm sóc khách hàng qua tin nhắn",scene:"Một khách nhắn tin hỏi về đơn hàng chưa nhận được.",partner:"Khách hàng",ind:"ecom",work:true,lines:[{r:"A",t:"Hi, I ordered three days ago but I haven't got it yet.",v:"Chào shop, tôi đặt hàng ba ngày rồi mà chưa nhận được."},{r:"B",t:"Hi! Sorry for the wait. Can you send me your order number?",v:"Chào chị! Xin lỗi vì để chị chờ. Chị gửi em mã đơn hàng nhé?"},{r:"A",t:"It's 88213.",v:"Mã là 88213."},{r:"B",t:"Thanks. Your order left our warehouse yesterday. It's with the delivery company now.",v:"Cảm ơn chị. Đơn đã rời kho hôm qua, hiện đang ở đơn vị vận chuyển."},{r:"A",t:"When will it arrive?",v:"Khi nào thì đến?"},{r:"B",t:"It should arrive tomorrow. Here's the tracking link.",v:"Ngày mai sẽ đến ạ. Đây là đường link theo dõi đơn."},{r:"A",t:"Can I pay when it arrives?",v:"Tôi trả tiền khi nhận hàng được không?"},{r:"B",t:"Yes, you chose cash on delivery, so you pay the driver.",v:"Được ạ, chị chọn thanh toán khi nhận hàng nên trả tiền cho tài xế."}],phrases:[{t:"Hi! Sorry for the wait. Can you send me your order number?",v:"Chào chị! Xin lỗi vì để chị chờ. Chị gửi em mã đơn hàng nhé?"},{t:"Thanks. Your order left our warehouse yesterday. It's with the delivery company now.",v:"Cảm ơn chị. Đơn đã rời kho hôm qua, hiện đang ở đơn vị vận chuyển."},{t:"It should arrive tomorrow. Here's the tracking link.",v:"Ngày mai sẽ đến ạ. Đây là đường link theo dõi đơn."},{t:"Yes, you chose cash on delivery, so you pay the driver.",v:"Được ạ, chị chọn thanh toán khi nhận hàng nên trả tiền cho tài xế."}],notes:[{h:"Sorry for the wait",b:"Cách xin lỗi ngắn gọn, lịch sự khi khách phải chờ. Không cần nói dài."},{h:"should + động từ để dự đoán",b:"\"It should arrive tomorrow\" là chắc là mai sẽ đến (dự đoán khá chắc chắn)."}]},
 {id:"en-w-ecom-sale",title:"Lên kế hoạch ngày siêu sale",scene:"Nhóm bán hàng online chuẩn bị cho đợt sale 11/11.",partner:"Trưởng nhóm",ind:"ecom",work:true,lines:[{r:"A",t:"The 11.11 sale is next week. Are we ready?",v:"Tuần sau là sale 11.11 rồi. Mình sẵn sàng chưa?"},{r:"B",t:"Almost. We've chosen twenty products for flash sales.",v:"Gần xong rồi. Mình đã chọn hai mươi sản phẩm để bán chớp nhoáng."},{r:"A",t:"What discounts are we giving?",v:"Mình giảm giá bao nhiêu?"},{r:"B",t:"Up to fifty percent, plus free shipping for orders over two hundred thousand dong.",v:"Giảm đến năm mươi phần trăm, thêm miễn phí vận chuyển cho đơn trên hai trăm nghìn đồng."},{r:"A",t:"Do we have enough stock?",v:"Mình có đủ hàng không?"},{r:"B",t:"We ordered extra for the top ten products.",v:"Mình đã nhập thêm cho mười sản phẩm bán chạy nhất."},{r:"A",t:"And customer service?",v:"Còn chăm sóc khách hàng?"},{r:"B",t:"Two more people will answer messages from 8 p.m. to midnight.",v:"Sẽ có thêm hai người trả lời tin nhắn từ tám giờ tối đến nửa đêm."}],phrases:[{t:"Almost. We've chosen twenty products for flash sales.",v:"Gần xong rồi. Mình đã chọn hai mươi sản phẩm để bán chớp nhoáng."},{t:"Up to fifty percent, plus free shipping for orders over two hundred thousand dong.",v:"Giảm đến năm mươi phần trăm, thêm miễn phí vận chuyển cho đơn trên hai trăm nghìn đồng."},{t:"We ordered extra for the top ten products.",v:"Mình đã nhập thêm cho mười sản phẩm bán chạy nhất."},{t:"Two more people will answer messages from 8 p.m. to midnight.",v:"Sẽ có thêm hai người trả lời tin nhắn từ tám giờ tối đến nửa đêm."}],notes:[{h:"up to",b:"\"Up to fifty percent\" là giảm tối đa năm mươi phần trăm, tức có sản phẩm giảm ít hơn."},{h:"orders over...",b:"\"Orders over 200,000 dong\" là đơn hàng trên hai trăm nghìn đồng."}]},
 {id:"en-w-mfg-tour",title:"Giới thiệu dây chuyền sản xuất",scene:"Bạn dẫn khách hàng nước ngoài tham quan nhà máy may.",partner:"Khách hàng",ind:"mfg",work:true,lines:[{r:"A",t:"Thanks for showing us around.",v:"Cảm ơn anh đã dẫn chúng tôi đi tham quan."},{r:"B",t:"You're welcome. This is our main production line.",v:"Không có gì. Đây là dây chuyền sản xuất chính của chúng tôi."},{r:"A",t:"How many workers do you have?",v:"Nhà máy có bao nhiêu công nhân?"},{r:"B",t:"About five hundred workers in two shifts.",v:"Khoảng năm trăm công nhân làm hai ca."},{r:"A",t:"What's your monthly capacity?",v:"Công suất mỗi tháng là bao nhiêu?"},{r:"B",t:"We can produce around one hundred thousand shirts a month.",v:"Chúng tôi sản xuất được khoảng một trăm nghìn áo sơ mi mỗi tháng."},{r:"A",t:"How do you check quality?",v:"Các anh kiểm tra chất lượng thế nào?"},{r:"B",t:"Every product is checked twice, and we have an ISO 9001 certificate.",v:"Mỗi sản phẩm được kiểm tra hai lần, và chúng tôi có chứng nhận ISO 9001."}],phrases:[{t:"You're welcome. This is our main production line.",v:"Không có gì. Đây là dây chuyền sản xuất chính của chúng tôi."},{t:"About five hundred workers in two shifts.",v:"Khoảng năm trăm công nhân làm hai ca."},{t:"We can produce around one hundred thousand shirts a month.",v:"Chúng tôi sản xuất được khoảng một trăm nghìn áo sơ mi mỗi tháng."},{t:"Every product is checked twice, and we have an ISO 9001 certificate.",v:"Mỗi sản phẩm được kiểm tra hai lần, và chúng tôi có chứng nhận ISO 9001."}],notes:[{h:"show someone around",b:"\"Show us around\" là dẫn ai đi tham quan một nơi."},{h:"Bị động để nói về quy trình",b:"\"Every product is checked twice\" dùng bị động vì người nghe quan tâm sản phẩm, không quan tâm ai kiểm tra."}]},
 {id:"en-w-mfg-problem",title:"Báo sự cố máy móc",scene:"Một máy trên dây chuyền bị hỏng. Bạn là tổ trưởng báo cho quản lý.",partner:"Quản lý sản xuất",ind:"mfg",work:true,lines:[{r:"A",t:"What's happening on line three?",v:"Dây chuyền ba có chuyện gì vậy?"},{r:"B",t:"Machine number five broke down an hour ago.",v:"Máy số năm bị hỏng cách đây một giờ."},{r:"A",t:"Do you know why?",v:"Biết nguyên nhân không?"},{r:"B",t:"The technician thinks a part is worn out. He's replacing it now.",v:"Kỹ thuật viên nghĩ là một linh kiện bị mòn. Anh ấy đang thay."},{r:"A",t:"How long will it take?",v:"Mất bao lâu?"},{r:"B",t:"About two hours. Meanwhile, we moved the workers to line two.",v:"Khoảng hai tiếng. Trong lúc đó, tôi đã chuyển công nhân sang dây chuyền hai."},{r:"A",t:"Will we still meet today's target?",v:"Hôm nay có đạt chỉ tiêu không?"},{r:"B",t:"We'll be about five percent behind, but we can catch up with one hour of overtime.",v:"Sẽ chậm khoảng năm phần trăm, nhưng tăng ca một giờ là bắt kịp."}],phrases:[{t:"Machine number five broke down an hour ago.",v:"Máy số năm bị hỏng cách đây một giờ."},{t:"The technician thinks a part is worn out. He's replacing it now.",v:"Kỹ thuật viên nghĩ là một linh kiện bị mòn. Anh ấy đang thay."},{t:"About two hours. Meanwhile, we moved the workers to line two.",v:"Khoảng hai tiếng. Trong lúc đó, tôi đã chuyển công nhân sang dây chuyền hai."},{t:"We'll be about five percent behind, but we can catch up with one hour of overtime.",v:"Sẽ chậm khoảng năm phần trăm, nhưng tăng ca một giờ là bắt kịp."}],notes:[{h:"break down",b:"\"Break down\" là (máy) bị hỏng, ngừng chạy. Danh từ: breakdown."},{h:"Báo sự cố đủ ba ý",b:"Nói rõ: chuyện gì xảy ra, đang xử lý thế nào, ảnh hưởng ra sao. Quản lý sẽ yên tâm hơn."}]},
 {id:"en-w-mfg-order",title:"Trao đổi đơn hàng với khách",scene:"Khách hàng muốn thay đổi đơn hàng đang sản xuất.",partner:"Khách hàng",ind:"mfg",work:true,lines:[{r:"A",t:"Can we change the color of our order from blue to green?",v:"Chúng tôi đổi màu đơn hàng từ xanh dương sang xanh lá được không?"},{r:"B",t:"Let me check. We've already cut the fabric for half of the order.",v:"Để tôi kiểm tra. Chúng tôi đã cắt vải cho một nửa đơn hàng rồi."},{r:"A",t:"What about the other half?",v:"Còn nửa còn lại thì sao?"},{r:"B",t:"We can change that, but we need to buy new fabric first.",v:"Cái đó thì đổi được, nhưng chúng tôi cần mua vải mới trước."},{r:"A",t:"Will it delay the delivery?",v:"Có làm chậm giao hàng không?"},{r:"B",t:"Yes, by about ten days. There's also an extra cost for the new fabric.",v:"Có, chậm khoảng mười ngày. Ngoài ra có thêm chi phí cho vải mới."},{r:"A",t:"OK, please send me the new price and date.",v:"Được, gửi tôi giá và ngày giao mới nhé."},{r:"B",t:"I will. Please confirm by email before we start.",v:"Vâng. Anh xác nhận qua email trước khi chúng tôi bắt đầu nhé."}],phrases:[{t:"Let me check. We've already cut the fabric for half of the order.",v:"Để tôi kiểm tra. Chúng tôi đã cắt vải cho một nửa đơn hàng rồi."},{t:"We can change that, but we need to buy new fabric first.",v:"Cái đó thì đổi được, nhưng chúng tôi cần mua vải mới trước."},{t:"Yes, by about ten days. There's also an extra cost for the new fabric.",v:"Có, chậm khoảng mười ngày. Ngoài ra có thêm chi phí cho vải mới."},{t:"I will. Please confirm by email before we start.",v:"Vâng. Anh xác nhận qua email trước khi chúng tôi bắt đầu nhé."}],notes:[{h:"Trả lời rõ ràng về tác động",b:"Khi khách muốn thay đổi, nói rõ ảnh hưởng đến thời gian (delay) và chi phí (extra cost)."},{h:"Xác nhận bằng văn bản",b:"\"Please confirm by email\" giúp tránh tranh cãi sau này. Đây là thói quen quan trọng."}]},
 {id:"en-w-cons-site",title:"Họp tại công trường",scene:"Bạn là kỹ sư giám sát, báo cáo tiến độ cho chủ đầu tư.",partner:"Chủ đầu tư",ind:"cons",work:true,lines:[{r:"A",t:"How is the project going?",v:"Dự án đang tiến triển thế nào?"},{r:"B",t:"We've finished the foundation and the first three floors.",v:"Chúng tôi đã xong phần móng và ba tầng đầu."},{r:"A",t:"Are we on schedule?",v:"Có đúng tiến độ không?"},{r:"B",t:"We're about one week behind because of the heavy rain.",v:"Chậm khoảng một tuần do mưa lớn."},{r:"A",t:"Can you catch up?",v:"Có bắt kịp được không?"},{r:"B",t:"Yes, we'll add a second team to work on weekends.",v:"Có, chúng tôi sẽ thêm một đội làm cuối tuần."},{r:"A",t:"What about safety?",v:"Còn an toàn thì sao?"},{r:"B",t:"Everyone on site must wear a helmet and safety boots. We check every morning.",v:"Mọi người trên công trường phải đội mũ bảo hộ và đi giày bảo hộ. Sáng nào chúng tôi cũng kiểm tra."}],phrases:[{t:"We've finished the foundation and the first three floors.",v:"Chúng tôi đã xong phần móng và ba tầng đầu."},{t:"We're about one week behind because of the heavy rain.",v:"Chậm khoảng một tuần do mưa lớn."},{t:"Yes, we'll add a second team to work on weekends.",v:"Có, chúng tôi sẽ thêm một đội làm cuối tuần."},{t:"Everyone on site must wear a helmet and safety boots. We check every morning.",v:"Mọi người trên công trường phải đội mũ bảo hộ và đi giày bảo hộ. Sáng nào chúng tôi cũng kiểm tra."}],notes:[{h:"on schedule / behind schedule",b:"on schedule là đúng tiến độ, behind schedule là chậm tiến độ, ahead of schedule là vượt tiến độ."},{h:"Giải thích nguyên nhân bằng because of",b:"\"Because of the heavy rain\" + danh từ. Nếu là cả câu thì dùng because: because it rained a lot."}]},
 {id:"en-w-cons-design",title:"Trao đổi bản thiết kế với khách",scene:"Bạn là kiến trúc sư, trình bày bản thiết kế nhà cho khách hàng.",partner:"Khách hàng",ind:"cons",work:true,lines:[{r:"A",t:"Can you show me the new design?",v:"Anh cho tôi xem bản thiết kế mới được không?"},{r:"B",t:"Of course. Here's the floor plan for the ground floor.",v:"Tất nhiên. Đây là mặt bằng tầng trệt."},{r:"A",t:"The living room looks small.",v:"Phòng khách trông hơi nhỏ."},{r:"B",t:"We can remove this wall and join it with the dining room.",v:"Chúng ta có thể bỏ bức tường này và nối với phòng ăn."},{r:"A",t:"Good idea. What about natural light?",v:"Ý hay. Còn ánh sáng tự nhiên?"},{r:"B",t:"We'll add large windows facing south.",v:"Chúng tôi sẽ thêm cửa sổ lớn hướng nam."},{r:"A",t:"Will that change the cost?",v:"Như vậy có thay đổi chi phí không?"},{r:"B",t:"A little. I'll update the drawings and the budget by Friday.",v:"Một chút. Tôi sẽ cập nhật bản vẽ và dự toán trước thứ Sáu."}],phrases:[{t:"Of course. Here's the floor plan for the ground floor.",v:"Tất nhiên. Đây là mặt bằng tầng trệt."},{t:"We can remove this wall and join it with the dining room.",v:"Chúng ta có thể bỏ bức tường này và nối với phòng ăn."},{t:"We'll add large windows facing south.",v:"Chúng tôi sẽ thêm cửa sổ lớn hướng nam."},{t:"A little. I'll update the drawings and the budget by Friday.",v:"Một chút. Tôi sẽ cập nhật bản vẽ và dự toán trước thứ Sáu."}],notes:[{h:"floor plan",b:"Floor plan là bản vẽ mặt bằng. Ground floor (Anh) = first floor (Mỹ) là tầng trệt."},{h:"Đưa giải pháp ngay khi khách chê",b:"Khách nói \"looks small\", kiến trúc sư đưa ngay phương án: \"We can remove this wall...\""}]},
 {id:"en-w-cons-supply",title:"Đặt vật liệu xây dựng",scene:"Bạn gọi nhà cung cấp để đặt xi măng và thép.",partner:"Nhà cung cấp",ind:"cons",work:true,lines:[{r:"A",t:"Hello, Minh Phat Materials.",v:"A lô, Vật liệu Minh Phát xin nghe."},{r:"B",t:"Hi, I'd like to order two hundred bags of cement and five tons of steel.",v:"Chào anh, tôi muốn đặt hai trăm bao xi măng và năm tấn thép."},{r:"A",t:"Which type of steel?",v:"Thép loại nào ạ?"},{r:"B",t:"Twelve-millimeter steel bars. Can you deliver to the site in District 7?",v:"Thép thanh mười hai li. Anh giao đến công trường ở Quận 7 được không?"},{r:"A",t:"Yes. When do you need them?",v:"Được. Khi nào chị cần?"},{r:"B",t:"Before eight a.m. on Monday, please. The truck can't enter after nine.",v:"Trước tám giờ sáng thứ Hai nhé. Sau chín giờ xe tải không vào được."},{r:"A",t:"No problem. Payment within fifteen days, right?",v:"Không vấn đề. Thanh toán trong mười lăm ngày nhé?"},{r:"B",t:"Yes. Please send the invoice with the delivery note.",v:"Vâng. Anh gửi hóa đơn kèm phiếu giao hàng nhé."}],phrases:[{t:"Hi, I'd like to order two hundred bags of cement and five tons of steel.",v:"Chào anh, tôi muốn đặt hai trăm bao xi măng và năm tấn thép."},{t:"Twelve-millimeter steel bars. Can you deliver to the site in District 7?",v:"Thép thanh mười hai li. Anh giao đến công trường ở Quận 7 được không?"},{t:"Before eight a.m. on Monday, please. The truck can't enter after nine.",v:"Trước tám giờ sáng thứ Hai nhé. Sau chín giờ xe tải không vào được."},{t:"Yes. Please send the invoice with the delivery note.",v:"Vâng. Anh gửi hóa đơn kèm phiếu giao hàng nhé."}],notes:[{h:"Đơn vị đo",b:"ton (tấn), bag (bao), millimeter (mi-li-mét). Người Việt hay nói \"li\", tiếng Anh là millimeter."},{h:"right? để xác nhận",b:"\"Payment within fifteen days, right?\" là câu hỏi đuôi ngắn để xác nhận điều đã biết."}]},
 {id:"en-w-re-view",title:"Dẫn khách xem căn hộ",scene:"Bạn là môi giới, dẫn khách xem căn hộ để bán.",partner:"Khách hàng",ind:"re",work:true,lines:[{r:"A",t:"What's the size of this apartment?",v:"Căn hộ này rộng bao nhiêu?"},{r:"B",t:"It's seventy-five square meters, with two bedrooms and two bathrooms.",v:"Rộng bảy mươi lăm mét vuông, có hai phòng ngủ và hai phòng tắm."},{r:"A",t:"Which direction does the balcony face?",v:"Ban công hướng nào?"},{r:"B",t:"It faces east, so you get the morning sun and it's cool in the afternoon.",v:"Hướng đông, nên có nắng sáng và buổi chiều mát."},{r:"A",t:"How much is it?",v:"Giá bao nhiêu?"},{r:"B",t:"Three point two billion dong, including furniture.",v:"Ba tỷ hai, đã bao gồm nội thất."},{r:"A",t:"Is the price negotiable?",v:"Giá có thương lượng được không?"},{r:"B",t:"The owner is flexible. If you're serious, I can arrange a meeting with him.",v:"Chủ nhà khá linh hoạt. Nếu anh thực sự quan tâm, tôi có thể sắp xếp gặp chủ nhà."}],phrases:[{t:"It's seventy-five square meters, with two bedrooms and two bathrooms.",v:"Rộng bảy mươi lăm mét vuông, có hai phòng ngủ và hai phòng tắm."},{t:"It faces east, so you get the morning sun and it's cool in the afternoon.",v:"Hướng đông, nên có nắng sáng và buổi chiều mát."},{t:"Three point two billion dong, including furniture.",v:"Ba tỷ hai, đã bao gồm nội thất."},{t:"The owner is flexible. If you're serious, I can arrange a meeting with him.",v:"Chủ nhà khá linh hoạt. Nếu anh thực sự quan tâm, tôi có thể sắp xếp gặp chủ nhà."}],notes:[{h:"Diện tích",b:"seventy-five square meters là 75 mét vuông, viết tắt 75 m²."},{h:"negotiable",b:"\"Is the price negotiable?\" là giá có thương lượng được không. Câu trả lời mềm: \"The owner is flexible.\""}]},
 {id:"en-w-re-contract",title:"Giải thích hợp đồng mua bán",scene:"Khách hàng đã đồng ý mua. Bạn giải thích các bước thanh toán.",partner:"Khách hàng",ind:"re",work:true,lines:[{r:"A",t:"What are the next steps?",v:"Các bước tiếp theo là gì?"},{r:"B",t:"First, we sign a deposit agreement, and you pay ten percent.",v:"Đầu tiên, chúng ta ký thỏa thuận đặt cọc, anh trả mười phần trăm."},{r:"A",t:"And then?",v:"Rồi sau đó?"},{r:"B",t:"Within thirty days, we sign the sales contract at the notary office.",v:"Trong ba mươi ngày, chúng ta ký hợp đồng mua bán ở văn phòng công chứng."},{r:"A",t:"When do I pay the rest?",v:"Khi nào tôi trả phần còn lại?"},{r:"B",t:"On the same day. Then we apply for the ownership certificate in your name.",v:"Cùng ngày đó. Sau đó chúng ta làm thủ tục sang tên sổ hồng cho anh."},{r:"A",t:"Who pays the taxes and fees?",v:"Ai trả thuế và phí?"},{r:"B",t:"Usually the seller pays income tax, and the buyer pays the registration fee.",v:"Thường người bán trả thuế thu nhập, người mua trả lệ phí trước bạ."}],phrases:[{t:"First, we sign a deposit agreement, and you pay ten percent.",v:"Đầu tiên, chúng ta ký thỏa thuận đặt cọc, anh trả mười phần trăm."},{t:"Within thirty days, we sign the sales contract at the notary office.",v:"Trong ba mươi ngày, chúng ta ký hợp đồng mua bán ở văn phòng công chứng."},{t:"On the same day. Then we apply for the ownership certificate in your name.",v:"Cùng ngày đó. Sau đó chúng ta làm thủ tục sang tên sổ hồng cho anh."},{t:"Usually the seller pays income tax, and the buyer pays the registration fee.",v:"Thường người bán trả thuế thu nhập, người mua trả lệ phí trước bạ."}],notes:[{h:"Liệt kê các bước",b:"First…, then…, within thirty days… giúp khách hiểu rõ quy trình."},{h:"in your name",b:"\"In your name\" là đứng tên bạn. Sổ hồng gọi là ownership certificate hoặc land use right certificate."}]},
 {id:"en-w-re-rent",title:"Cho thuê văn phòng",scene:"Một công ty nước ngoài muốn thuê văn phòng. Bạn là nhân viên cho thuê.",partner:"Khách thuê",ind:"re",work:true,lines:[{r:"A",t:"We need an office for about thirty people.",v:"Chúng tôi cần văn phòng cho khoảng ba mươi người."},{r:"B",t:"We have a two hundred square meter space on the tenth floor.",v:"Chúng tôi có một mặt bằng hai trăm mét vuông ở tầng mười."},{r:"A",t:"What's the rent?",v:"Giá thuê bao nhiêu?"},{r:"B",t:"Twenty dollars per square meter per month, plus a service charge.",v:"Hai mươi đô một mét vuông mỗi tháng, cộng phí dịch vụ."},{r:"A",t:"What does the service charge include?",v:"Phí dịch vụ bao gồm những gì?"},{r:"B",t:"Air conditioning, cleaning, security and parking for motorbikes.",v:"Điều hòa, vệ sinh, bảo vệ và chỗ để xe máy."},{r:"A",t:"What's the minimum lease?",v:"Thời hạn thuê tối thiểu là bao lâu?"},{r:"B",t:"Two years, with a three-month deposit.",v:"Hai năm, đặt cọc ba tháng."}],phrases:[{t:"We have a two hundred square meter space on the tenth floor.",v:"Chúng tôi có một mặt bằng hai trăm mét vuông ở tầng mười."},{t:"Twenty dollars per square meter per month, plus a service charge.",v:"Hai mươi đô một mét vuông mỗi tháng, cộng phí dịch vụ."},{t:"Air conditioning, cleaning, security and parking for motorbikes.",v:"Điều hòa, vệ sinh, bảo vệ và chỗ để xe máy."},{t:"Two years, with a three-month deposit.",v:"Hai năm, đặt cọc ba tháng."}],notes:[{h:"per square meter per month",b:"Giá thuê văn phòng thường tính theo mét vuông mỗi tháng."},{h:"lease",b:"Lease là hợp đồng thuê dài hạn. Tenant là người thuê, landlord là chủ cho thuê."}]},
 {id:"en-w-air-checkin",title:"Làm thủ tục tại quầy",scene:"Bạn là nhân viên mặt đất, làm thủ tục cho hành khách.",partner:"Hành khách",ind:"air",work:true,lines:[{r:"A",t:"Hi, I'm flying to Singapore.",v:"Chào chị, tôi bay đi Singapore."},{r:"B",t:"May I see your passport and ticket, please?",v:"Cho tôi xem hộ chiếu và vé được không ạ?"},{r:"A",t:"Here you are.",v:"Đây."},{r:"B",t:"Would you like a window seat or an aisle seat?",v:"Anh muốn ghế cạnh cửa sổ hay cạnh lối đi?"},{r:"A",t:"An aisle seat, please.",v:"Ghế cạnh lối đi."},{r:"B",t:"Please put your bag on the scale. Your allowance is twenty kilos.",v:"Anh đặt túi lên cân nhé. Hành lý miễn cước của anh là hai mươi ký."},{r:"A",t:"Is it OK?",v:"Có ổn không?"},{r:"B",t:"Yes, eighteen kilos. Here's your boarding pass. Boarding starts at 9:40 at gate 12.",v:"Ổn, mười tám ký. Đây là thẻ lên máy bay. Lên máy bay lúc 9 giờ 40 ở cửa 12."}],phrases:[{t:"May I see your passport and ticket, please?",v:"Cho tôi xem hộ chiếu và vé được không ạ?"},{t:"Would you like a window seat or an aisle seat?",v:"Anh muốn ghế cạnh cửa sổ hay cạnh lối đi?"},{t:"Please put your bag on the scale. Your allowance is twenty kilos.",v:"Anh đặt túi lên cân nhé. Hành lý miễn cước của anh là hai mươi ký."},{t:"Yes, eighteen kilos. Here's your boarding pass. Boarding starts at 9:40 at gate 12.",v:"Ổn, mười tám ký. Đây là thẻ lên máy bay. Lên máy bay lúc 9 giờ 40 ở cửa 12."}],notes:[{h:"window seat / aisle seat",b:"window seat là ghế cửa sổ, aisle seat là ghế lối đi (aisle đọc là /aɪl/, chữ s câm)."},{h:"allowance",b:"Baggage allowance là hành lý được mang miễn cước."}]},
 {id:"en-w-air-cabin",title:"Phục vụ trên máy bay",scene:"Bạn là tiếp viên, phục vụ hành khách trên chuyến bay.",partner:"Hành khách",ind:"air",work:true,lines:[{r:"A",t:"Excuse me, can I have some water?",v:"Xin lỗi, cho tôi xin ít nước được không?"},{r:"B",t:"Of course. We'll serve drinks after take-off.",v:"Tất nhiên. Chúng tôi sẽ phục vụ đồ uống sau khi cất cánh."},{r:"A",t:"OK. Also, I can't find space for my bag.",v:"Được. Ngoài ra tôi không tìm được chỗ để túi."},{r:"B",t:"Let me help you. There's space in the overhead bin over there.",v:"Để tôi giúp anh. Có chỗ trong hộc hành lý phía trên đằng kia."},{r:"A",t:"Thanks. When do we land?",v:"Cảm ơn. Khi nào hạ cánh?"},{r:"B",t:"We'll land in Singapore at 2:15 local time.",v:"Chúng ta sẽ hạ cánh ở Singapore lúc 2 giờ 15 giờ địa phương."},{r:"A",t:"Great.",v:"Tốt quá."},{r:"B",t:"Please fasten your seat belt. We're about to take off.",v:"Xin anh thắt dây an toàn. Chúng ta chuẩn bị cất cánh."}],phrases:[{t:"Of course. We'll serve drinks after take-off.",v:"Tất nhiên. Chúng tôi sẽ phục vụ đồ uống sau khi cất cánh."},{t:"Let me help you. There's space in the overhead bin over there.",v:"Để tôi giúp anh. Có chỗ trong hộc hành lý phía trên đằng kia."},{t:"We'll land in Singapore at 2:15 local time.",v:"Chúng ta sẽ hạ cánh ở Singapore lúc 2 giờ 15 giờ địa phương."},{t:"Please fasten your seat belt. We're about to take off.",v:"Xin anh thắt dây an toàn. Chúng ta chuẩn bị cất cánh."}],notes:[{h:"be about to",b:"\"We're about to take off\" là sắp cất cánh ngay."},{h:"Câu lịch sự của tiếp viên",b:"Please fasten your seat belt / Please turn off your phone… luôn bắt đầu bằng Please."}]},
 {id:"en-w-air-delay",title:"Thông báo chuyến bay bị hoãn",scene:"Chuyến bay bị hoãn. Bạn là nhân viên hãng, giải thích với hành khách.",partner:"Hành khách",ind:"air",work:true,lines:[{r:"A",t:"Why is my flight delayed?",v:"Sao chuyến bay của tôi bị hoãn?"},{r:"B",t:"I'm sorry. There's a technical problem with the aircraft.",v:"Tôi xin lỗi. Máy bay gặp sự cố kỹ thuật."},{r:"A",t:"How long will we wait?",v:"Chúng tôi phải chờ bao lâu?"},{r:"B",t:"About three hours. The new departure time is 6:30.",v:"Khoảng ba tiếng. Giờ khởi hành mới là 6 giờ 30."},{r:"A",t:"I'll miss my connecting flight.",v:"Tôi sẽ lỡ chuyến bay nối tiếp."},{r:"B",t:"Don't worry. I'll rebook you on the next flight at no extra cost.",v:"Anh đừng lo. Tôi sẽ đổi cho anh sang chuyến tiếp theo, không mất thêm phí."},{r:"A",t:"Thank you.",v:"Cảm ơn."},{r:"B",t:"Here's a meal voucher for the restaurant on the second floor.",v:"Đây là phiếu ăn cho nhà hàng ở tầng hai."}],phrases:[{t:"I'm sorry. There's a technical problem with the aircraft.",v:"Tôi xin lỗi. Máy bay gặp sự cố kỹ thuật."},{t:"About three hours. The new departure time is 6:30.",v:"Khoảng ba tiếng. Giờ khởi hành mới là 6 giờ 30."},{t:"Don't worry. I'll rebook you on the next flight at no extra cost.",v:"Anh đừng lo. Tôi sẽ đổi cho anh sang chuyến tiếp theo, không mất thêm phí."},{t:"Here's a meal voucher for the restaurant on the second floor.",v:"Đây là phiếu ăn cho nhà hàng ở tầng hai."}],notes:[{h:"Xin lỗi và đưa giải pháp",b:"Khi khách phiền lòng, nhân viên xin lỗi, giải thích ngắn rồi đưa giải pháp cụ thể: rebook, meal voucher."},{h:"connecting flight",b:"Chuyến bay nối tiếp. Transit là quá cảnh."}]},
 {id:"en-w-pharma-rep",title:"Trình dược viên gặp bác sĩ",scene:"Bạn là trình dược viên, giới thiệu thuốc mới cho bác sĩ.",partner:"Bác sĩ",ind:"pharma",work:true,lines:[{r:"A",t:"You have five minutes. What's new?",v:"Anh có năm phút. Có gì mới?"},{r:"B",t:"Thank you, doctor. We've launched a new medicine for high blood pressure.",v:"Cảm ơn bác sĩ. Bên em vừa ra mắt một thuốc mới điều trị cao huyết áp."},{r:"A",t:"How is it different?",v:"Nó khác gì?"},{r:"B",t:"Patients only need to take one tablet a day.",v:"Bệnh nhân chỉ cần uống một viên mỗi ngày."},{r:"A",t:"What about side effects?",v:"Còn tác dụng phụ?"},{r:"B",t:"In clinical trials, side effects were mild and rare. Here's the study.",v:"Trong thử nghiệm lâm sàng, tác dụng phụ nhẹ và hiếm gặp. Đây là nghiên cứu ạ."},{r:"A",t:"I'll read it.",v:"Tôi sẽ đọc."},{r:"B",t:"Thank you. I can also leave some samples for your patients.",v:"Cảm ơn bác sĩ. Em có thể để lại một ít mẫu cho bệnh nhân."}],phrases:[{t:"Thank you, doctor. We've launched a new medicine for high blood pressure.",v:"Cảm ơn bác sĩ. Bên em vừa ra mắt một thuốc mới điều trị cao huyết áp."},{t:"Patients only need to take one tablet a day.",v:"Bệnh nhân chỉ cần uống một viên mỗi ngày."},{t:"In clinical trials, side effects were mild and rare. Here's the study.",v:"Trong thử nghiệm lâm sàng, tác dụng phụ nhẹ và hiếm gặp. Đây là nghiên cứu ạ."},{t:"Thank you. I can also leave some samples for your patients.",v:"Cảm ơn bác sĩ. Em có thể để lại một ít mẫu cho bệnh nhân."}],notes:[{h:"Nói ngắn gọn với bác sĩ",b:"Bác sĩ bận, nên nói ngay điểm khác biệt chính và đưa bằng chứng (study)."},{h:"clinical trial",b:"Thử nghiệm lâm sàng, bằng chứng quan trọng nhất của một thuốc mới."}]},
 {id:"en-w-pharma-lab",title:"Báo cáo kết quả kiểm nghiệm",scene:"Bạn làm ở phòng kiểm nghiệm, báo cáo một lô thuốc không đạt.",partner:"Trưởng phòng chất lượng",ind:"pharma",work:true,lines:[{r:"A",t:"Any problems with batch 2305?",v:"Lô 2305 có vấn đề gì không?"},{r:"B",t:"Yes. The test results show the tablets dissolve too slowly.",v:"Có. Kết quả kiểm nghiệm cho thấy viên thuốc tan quá chậm."},{r:"A",t:"How slowly?",v:"Chậm thế nào?"},{r:"B",t:"Only seventy percent dissolved in thirty minutes. The standard is eighty-five.",v:"Chỉ tan bảy mươi phần trăm trong ba mươi phút. Tiêu chuẩn là tám mươi lăm."},{r:"A",t:"Did you test it again?",v:"Đã kiểm tra lại chưa?"},{r:"B",t:"Yes, three times. The results were the same.",v:"Rồi ạ, ba lần. Kết quả như nhau."},{r:"A",t:"Then we can't release it.",v:"Vậy không được xuất xưởng."},{r:"B",t:"I agree. I'll put the batch on hold and write a report.",v:"Em đồng ý. Em sẽ tạm giữ lô này và viết báo cáo."}],phrases:[{t:"Yes. The test results show the tablets dissolve too slowly.",v:"Có. Kết quả kiểm nghiệm cho thấy viên thuốc tan quá chậm."},{t:"Only seventy percent dissolved in thirty minutes. The standard is eighty-five.",v:"Chỉ tan bảy mươi phần trăm trong ba mươi phút. Tiêu chuẩn là tám mươi lăm."},{t:"Yes, three times. The results were the same.",v:"Rồi ạ, ba lần. Kết quả như nhau."},{t:"I agree. I'll put the batch on hold and write a report.",v:"Em đồng ý. Em sẽ tạm giữ lô này và viết báo cáo."}],notes:[{h:"So sánh với tiêu chuẩn",b:"\"The standard is eighty-five\" giúp người nghe hiểu ngay lô thuốc không đạt."},{h:"on hold",b:"\"Put the batch on hold\" là tạm giữ lại, chưa xử lý tiếp."}]},
 {id:"en-w-pharma-counter",title:"Bán thuốc theo đơn",scene:"Bạn là dược sĩ ở nhà thuốc, bán thuốc theo đơn của bác sĩ.",partner:"Khách hàng",ind:"pharma",work:true,lines:[{r:"A",t:"Hi, I have a prescription from my doctor.",v:"Chào chị, tôi có đơn thuốc của bác sĩ."},{r:"B",t:"Thank you. Let me check. This antibiotic is for seven days.",v:"Cảm ơn anh. Để tôi xem. Thuốc kháng sinh này dùng bảy ngày."},{r:"A",t:"How should I take it?",v:"Tôi uống thế nào?"},{r:"B",t:"One capsule twice a day, after breakfast and after dinner.",v:"Một viên con nhộng, ngày hai lần, sau bữa sáng và sau bữa tối."},{r:"A",t:"Can I drink alcohol?",v:"Tôi uống rượu bia được không?"},{r:"B",t:"No, please avoid alcohol while you take it.",v:"Không, anh tránh rượu bia trong thời gian uống thuốc."},{r:"A",t:"What if I feel better after three days?",v:"Nếu ba ngày đã khỏe thì sao?"},{r:"B",t:"Please finish all of it, even if you feel better.",v:"Anh vẫn uống hết, kể cả khi đã thấy khỏe hơn."}],phrases:[{t:"Thank you. Let me check. This antibiotic is for seven days.",v:"Cảm ơn anh. Để tôi xem. Thuốc kháng sinh này dùng bảy ngày."},{t:"One capsule twice a day, after breakfast and after dinner.",v:"Một viên con nhộng, ngày hai lần, sau bữa sáng và sau bữa tối."},{t:"No, please avoid alcohol while you take it.",v:"Không, anh tránh rượu bia trong thời gian uống thuốc."},{t:"Please finish all of it, even if you feel better.",v:"Anh vẫn uống hết, kể cả khi đã thấy khỏe hơn."}],notes:[{h:"Dặn dùng kháng sinh",b:"Luôn dặn uống đủ liệu trình: \"Please finish all of it, even if you feel better.\""},{h:"avoid + danh từ / V-ing",b:"\"Avoid alcohol\", \"avoid driving\" là tránh rượu bia, tránh lái xe."}]},
 {id:"en-w-edu-parent",title:"Họp phụ huynh",scene:"Bạn là giáo viên chủ nhiệm, trao đổi với phụ huynh về việc học của con.",partner:"Phụ huynh",ind:"edu",work:true,lines:[{r:"A",t:"How is my son doing in class?",v:"Con tôi học trên lớp thế nào ạ?"},{r:"B",t:"He's doing well in math, but he needs to work harder in English.",v:"Cháu học toán tốt, nhưng cần cố gắng hơn ở môn tiếng Anh."},{r:"A",t:"What's the problem with English?",v:"Môn tiếng Anh có vấn đề gì ạ?"},{r:"B",t:"He often forgets his homework, and his vocabulary is quite weak.",v:"Cháu hay quên làm bài tập về nhà, vốn từ vựng còn khá yếu."},{r:"A",t:"How can I help him at home?",v:"Ở nhà tôi giúp cháu thế nào được?"},{r:"B",t:"Please check his homework every evening and let him read English stories for fifteen minutes.",v:"Anh chị kiểm tra bài tập mỗi tối và cho cháu đọc truyện tiếng Anh mười lăm phút."},{r:"A",t:"OK, we'll try that.",v:"Vâng, chúng tôi sẽ thử."},{r:"B",t:"Thank you. Let's talk again after the mid-term exam.",v:"Cảm ơn anh chị. Mình trao đổi lại sau kỳ thi giữa kỳ nhé."}],phrases:[{t:"He's doing well in math, but he needs to work harder in English.",v:"Cháu học toán tốt, nhưng cần cố gắng hơn ở môn tiếng Anh."},{t:"He often forgets his homework, and his vocabulary is quite weak.",v:"Cháu hay quên làm bài tập về nhà, vốn từ vựng còn khá yếu."},{t:"Please check his homework every evening and let him read English stories for fifteen minutes.",v:"Anh chị kiểm tra bài tập mỗi tối và cho cháu đọc truyện tiếng Anh mười lăm phút."},{t:"Thank you. Let's talk again after the mid-term exam.",v:"Cảm ơn anh chị. Mình trao đổi lại sau kỳ thi giữa kỳ nhé."}],notes:[{h:"Khen trước, góp ý sau",b:"\"He's doing well in math, but…\" giúp phụ huynh dễ tiếp nhận góp ý hơn."},{h:"work harder",b:"\"Needs to work harder\" là cần cố gắng hơn, cách nói nhẹ nhàng thay cho \"is lazy\"."}]},
 {id:"en-w-edu-class",title:"Điều hành lớp học",scene:"Bạn là giáo viên tiếng Anh, hướng dẫn hoạt động nhóm trên lớp.",partner:"Học sinh",ind:"edu",work:true,lines:[{r:"A",t:"Teacher, what do we do now?",v:"Thưa cô, giờ chúng em làm gì ạ?"},{r:"B",t:"Please work in groups of four. Each group gets one picture.",v:"Các em làm việc nhóm bốn người. Mỗi nhóm nhận một bức tranh."},{r:"A",t:"What do we do with the picture?",v:"Làm gì với bức tranh ạ?"},{r:"B",t:"Describe it together and write five sentences. You have ten minutes.",v:"Cùng nhau mô tả và viết năm câu. Các em có mười phút."},{r:"A",t:"Can we use a dictionary?",v:"Chúng em dùng từ điển được không ạ?"},{r:"B",t:"Yes, but try to use words you already know first.",v:"Được, nhưng hãy thử dùng từ đã biết trước."},{r:"A",t:"We're finished!",v:"Chúng em xong rồi ạ!"},{r:"B",t:"Great job! Now one person from each group will read your sentences aloud.",v:"Giỏi lắm! Giờ mỗi nhóm cử một bạn đọc to các câu của nhóm."}],phrases:[{t:"Please work in groups of four. Each group gets one picture.",v:"Các em làm việc nhóm bốn người. Mỗi nhóm nhận một bức tranh."},{t:"Describe it together and write five sentences. You have ten minutes.",v:"Cùng nhau mô tả và viết năm câu. Các em có mười phút."},{t:"Yes, but try to use words you already know first.",v:"Được, nhưng hãy thử dùng từ đã biết trước."},{t:"Great job! Now one person from each group will read your sentences aloud.",v:"Giỏi lắm! Giờ mỗi nhóm cử một bạn đọc to các câu của nhóm."}],notes:[{h:"Hướng dẫn rõ ràng",b:"Giao việc bằng câu mệnh lệnh ngắn + giới hạn thời gian: \"You have ten minutes.\""},{h:"Khen học sinh",b:"Great job! / Well done! / Good try! Khen cụ thể giúp học sinh tự tin hơn."}]},
 {id:"en-w-edu-enroll",title:"Tư vấn khóa học",scene:"Bạn là tư vấn viên của trung tâm ngoại ngữ, tư vấn khóa học cho người lớn.",partner:"Học viên",ind:"edu",work:true,lines:[{r:"A",t:"I want to improve my English for work.",v:"Tôi muốn cải thiện tiếng Anh để đi làm."},{r:"B",t:"Great. First, please take a short placement test so we know your level.",v:"Tốt quá. Trước tiên anh làm bài kiểm tra xếp lớp ngắn để biết trình độ nhé."},{r:"A",t:"How long is the course?",v:"Khóa học kéo dài bao lâu?"},{r:"B",t:"Three months, three evenings a week, two hours each time.",v:"Ba tháng, ba buổi tối mỗi tuần, mỗi buổi hai tiếng."},{r:"A",t:"How many students are in a class?",v:"Mỗi lớp bao nhiêu học viên?"},{r:"B",t:"No more than twelve, so everyone has a chance to speak.",v:"Không quá mười hai, nên ai cũng có cơ hội nói."},{r:"A",t:"What's the fee?",v:"Học phí bao nhiêu?"},{r:"B",t:"Six million dong. If you register this week, you get a ten percent discount.",v:"Sáu triệu đồng. Nếu đăng ký trong tuần này, anh được giảm mười phần trăm."}],phrases:[{t:"Great. First, please take a short placement test so we know your level.",v:"Tốt quá. Trước tiên anh làm bài kiểm tra xếp lớp ngắn để biết trình độ nhé."},{t:"Three months, three evenings a week, two hours each time.",v:"Ba tháng, ba buổi tối mỗi tuần, mỗi buổi hai tiếng."},{t:"No more than twelve, so everyone has a chance to speak.",v:"Không quá mười hai, nên ai cũng có cơ hội nói."},{t:"Six million dong. If you register this week, you get a ten percent discount.",v:"Sáu triệu đồng. Nếu đăng ký trong tuần này, anh được giảm mười phần trăm."}],notes:[{h:"placement test",b:"Bài kiểm tra xếp lớp, để biết trình độ trước khi vào học."},{h:"no more than",b:"\"No more than twelve\" là không quá mười hai."}]},
 {id:"en-w-law-consult",title:"Tư vấn pháp lý lần đầu",scene:"Bạn là luật sư, gặp khách hàng lần đầu về tranh chấp hợp đồng.",partner:"Khách hàng",ind:"law",work:true,lines:[{r:"A",t:"My supplier didn't deliver the goods, but I already paid.",v:"Nhà cung cấp không giao hàng mà tôi đã trả tiền rồi."},{r:"B",t:"I see. Do you have a written contract with them?",v:"Tôi hiểu. Anh có hợp đồng bằng văn bản với họ không?"},{r:"A",t:"Yes, here it is.",v:"Có, đây ạ."},{r:"B",t:"Good. Clause seven says they must deliver within thirty days.",v:"Tốt. Điều bảy ghi họ phải giao trong ba mươi ngày."},{r:"A",t:"It's been sixty days.",v:"Đã sáu mươi ngày rồi."},{r:"B",t:"Then they have breached the contract. First, we'll send them a formal letter.",v:"Vậy họ đã vi phạm hợp đồng. Trước tiên chúng ta gửi thư yêu cầu chính thức."},{r:"A",t:"And if they don't answer?",v:"Nếu họ không trả lời thì sao?"},{r:"B",t:"Then we can take the case to court or to arbitration.",v:"Khi đó có thể đưa vụ việc ra tòa hoặc trọng tài."}],phrases:[{t:"I see. Do you have a written contract with them?",v:"Tôi hiểu. Anh có hợp đồng bằng văn bản với họ không?"},{t:"Good. Clause seven says they must deliver within thirty days.",v:"Tốt. Điều bảy ghi họ phải giao trong ba mươi ngày."},{t:"Then they have breached the contract. First, we'll send them a formal letter.",v:"Vậy họ đã vi phạm hợp đồng. Trước tiên chúng ta gửi thư yêu cầu chính thức."},{t:"Then we can take the case to court or to arbitration.",v:"Khi đó có thể đưa vụ việc ra tòa hoặc trọng tài."}],notes:[{h:"clause",b:"Clause là điều khoản trong hợp đồng. \"Clause seven says…\" là điều bảy ghi…"},{h:"breach",b:"Breach the contract là vi phạm hợp đồng. Danh từ: a breach of contract."}]},
 {id:"en-w-law-company",title:"Thành lập công ty",scene:"Một nhà đầu tư nước ngoài hỏi bạn về thủ tục thành lập công ty.",partner:"Nhà đầu tư",ind:"law",work:true,lines:[{r:"A",t:"I want to open a company in Vietnam.",v:"Tôi muốn mở công ty ở Việt Nam."},{r:"B",t:"What kind of business will you do?",v:"Anh sẽ kinh doanh lĩnh vực gì?"},{r:"A",t:"A software company.",v:"Công ty phần mềm."},{r:"B",t:"Good. For you, a limited liability company is the most common type.",v:"Tốt. Với anh, công ty trách nhiệm hữu hạn là loại hình phổ biến nhất."},{r:"A",t:"What documents do I need?",v:"Tôi cần giấy tờ gì?"},{r:"B",t:"Your passport, proof of address and a bank letter showing your capital.",v:"Hộ chiếu, giấy xác nhận địa chỉ và thư ngân hàng chứng minh vốn."},{r:"A",t:"How long does it take?",v:"Mất bao lâu?"},{r:"B",t:"About six to eight weeks for the investment certificate and the business license.",v:"Khoảng sáu đến tám tuần cho giấy chứng nhận đầu tư và giấy phép kinh doanh."}],phrases:[{t:"What kind of business will you do?",v:"Anh sẽ kinh doanh lĩnh vực gì?"},{t:"Good. For you, a limited liability company is the most common type.",v:"Tốt. Với anh, công ty trách nhiệm hữu hạn là loại hình phổ biến nhất."},{t:"Your passport, proof of address and a bank letter showing your capital.",v:"Hộ chiếu, giấy xác nhận địa chỉ và thư ngân hàng chứng minh vốn."},{t:"About six to eight weeks for the investment certificate and the business license.",v:"Khoảng sáu đến tám tuần cho giấy chứng nhận đầu tư và giấy phép kinh doanh."}],notes:[{h:"limited liability company",b:"Công ty TNHH, viết tắt LLC. Joint stock company là công ty cổ phần."},{h:"Ước lượng thời gian",b:"\"About six to eight weeks\" dùng khoảng thời gian để không hứa quá chắc."}]},
 {id:"en-w-law-labor",title:"Tư vấn luật lao động",scene:"Một nhân viên hỏi bạn về quyền lợi khi bị cho nghỉ việc.",partner:"Người lao động",ind:"law",work:true,lines:[{r:"A",t:"My company fired me without notice. Is that legal?",v:"Công ty cho tôi nghỉ không báo trước. Như vậy có hợp pháp không?"},{r:"B",t:"It depends on your contract. Do you have an indefinite-term contract?",v:"Còn tùy hợp đồng. Anh có hợp đồng không xác định thời hạn không?"},{r:"A",t:"Yes, I've worked there for four years.",v:"Có, tôi làm ở đó bốn năm rồi."},{r:"B",t:"Then they must give you at least forty-five days' notice.",v:"Vậy họ phải báo trước cho anh ít nhất bốn mươi lăm ngày."},{r:"A",t:"They didn't.",v:"Họ không báo."},{r:"B",t:"In that case, you may be entitled to compensation for the notice period.",v:"Trong trường hợp đó, anh có thể được bồi thường cho thời gian báo trước."},{r:"A",t:"What should I do now?",v:"Giờ tôi nên làm gì?"},{r:"B",t:"Keep all your emails and documents. I'll help you write a complaint.",v:"Anh giữ lại toàn bộ email và giấy tờ. Tôi sẽ giúp anh viết đơn khiếu nại."}],phrases:[{t:"It depends on your contract. Do you have an indefinite-term contract?",v:"Còn tùy hợp đồng. Anh có hợp đồng không xác định thời hạn không?"},{t:"Then they must give you at least forty-five days' notice.",v:"Vậy họ phải báo trước cho anh ít nhất bốn mươi lăm ngày."},{t:"In that case, you may be entitled to compensation for the notice period.",v:"Trong trường hợp đó, anh có thể được bồi thường cho thời gian báo trước."},{t:"Keep all your emails and documents. I'll help you write a complaint.",v:"Anh giữ lại toàn bộ email và giấy tờ. Tôi sẽ giúp anh viết đơn khiếu nại."}],notes:[{h:"It depends on…",b:"Luật sư thường trả lời \"It depends on…\" (còn tùy vào…) trước khi xem hồ sơ."},{h:"be entitled to",b:"\"Entitled to compensation\" là có quyền được bồi thường."}]},
 {id:"en-w-media-interview",title:"Phỏng vấn nhân vật",scene:"Bạn là phóng viên, phỏng vấn một doanh nhân trẻ.",partner:"Doanh nhân",ind:"media",work:true,lines:[{r:"A",t:"Thanks for having me.",v:"Cảm ơn đã mời tôi."},{r:"B",t:"Thank you for your time. Can you tell us how you started your business?",v:"Cảm ơn anh đã dành thời gian. Anh có thể kể chúng tôi nghe anh khởi nghiệp thế nào không?"},{r:"A",t:"I started selling coffee online during university.",v:"Tôi bắt đầu bán cà phê online khi còn học đại học."},{r:"B",t:"What was the biggest challenge?",v:"Thách thức lớn nhất là gì?"},{r:"A",t:"Finding money. Banks didn't trust a student.",v:"Tìm vốn. Ngân hàng không tin một sinh viên."},{r:"B",t:"How did you solve that?",v:"Anh giải quyết thế nào?"},{r:"A",t:"I borrowed from my family and saved every penny.",v:"Tôi vay gia đình và tiết kiệm từng đồng."},{r:"B",t:"Interesting. What advice would you give to young people?",v:"Thú vị. Anh có lời khuyên gì cho người trẻ?"}],phrases:[{t:"Thank you for your time. Can you tell us how you started your business?",v:"Cảm ơn anh đã dành thời gian. Anh có thể kể chúng tôi nghe anh khởi nghiệp thế nào không?"},{t:"What was the biggest challenge?",v:"Thách thức lớn nhất là gì?"},{t:"How did you solve that?",v:"Anh giải quyết thế nào?"},{t:"Interesting. What advice would you give to young people?",v:"Thú vị. Anh có lời khuyên gì cho người trẻ?"}],notes:[{h:"Câu hỏi mở",b:"Phóng viên dùng câu hỏi mở (how, what, why) để nhân vật kể nhiều hơn."},{h:"Can I quote you on that?",b:"Câu hỏi để xin phép trích dẫn lời nhân vật trên báo."}]},
 {id:"en-w-media-pr",title:"Lên kế hoạch truyền thông",scene:"Bạn làm PR, họp với khách hàng về chiến dịch ra mắt sản phẩm.",partner:"Khách hàng",ind:"media",work:true,lines:[{r:"A",t:"We're launching a new phone next month.",v:"Tháng sau chúng tôi ra mắt điện thoại mới."},{r:"B",t:"Who is your target audience?",v:"Khách hàng mục tiêu của anh là ai?"},{r:"A",t:"Students and young workers.",v:"Sinh viên và người trẻ mới đi làm."},{r:"B",t:"Then we should focus on TikTok and work with a few popular influencers.",v:"Vậy nên tập trung vào TikTok và hợp tác với vài người có ảnh hưởng nổi tiếng."},{r:"A",t:"What about the press?",v:"Còn báo chí?"},{r:"B",t:"We'll hold a press event and send a press release to twenty tech websites.",v:"Chúng ta sẽ tổ chức sự kiện báo chí và gửi thông cáo đến hai mươi trang công nghệ."},{r:"A",t:"How will we measure success?",v:"Đo lường thành công thế nào?"},{r:"B",t:"By views, engagement and the number of pre-orders.",v:"Bằng lượt xem, tương tác và số đơn đặt trước."}],phrases:[{t:"Who is your target audience?",v:"Khách hàng mục tiêu của anh là ai?"},{t:"Then we should focus on TikTok and work with a few popular influencers.",v:"Vậy nên tập trung vào TikTok và hợp tác với vài người có ảnh hưởng nổi tiếng."},{t:"We'll hold a press event and send a press release to twenty tech websites.",v:"Chúng ta sẽ tổ chức sự kiện báo chí và gửi thông cáo đến hai mươi trang công nghệ."},{t:"By views, engagement and the number of pre-orders.",v:"Bằng lượt xem, tương tác và số đơn đặt trước."}],notes:[{h:"target audience",b:"Đối tượng mục tiêu, nhóm người mà chiến dịch nhắm tới."},{h:"press release",b:"Thông cáo báo chí, văn bản chính thức gửi cho các báo."}]},
 {id:"en-w-media-news",title:"Họp tòa soạn",scene:"Bạn là biên tập viên, phân công tin bài trong buổi họp sáng.",partner:"Phóng viên",ind:"media",work:true,lines:[{r:"A",t:"What are the main stories today?",v:"Hôm nay có những tin chính nào?"},{r:"B",t:"The big one is the flood in the central region. Lan, can you cover it?",v:"Tin lớn là lũ ở miền Trung. Lan, em đưa tin được không?"},{r:"A",t:"Sure. Should I go there?",v:"Được ạ. Em có nên đến đó không?"},{r:"B",t:"Yes, take a photographer with you. We need photos by three p.m.",v:"Có, em đi cùng một phóng viên ảnh. Cần ảnh trước ba giờ chiều."},{r:"A",t:"What about the economy story?",v:"Còn tin kinh tế?"},{r:"B",t:"Nam will write about the new interest rates. Check the facts with the central bank.",v:"Nam sẽ viết về lãi suất mới. Kiểm tra số liệu với ngân hàng nhà nước nhé."},{r:"A",t:"When's the deadline?",v:"Hạn chót khi nào ạ?"},{r:"B",t:"Five p.m. for online, eight p.m. for the print edition.",v:"Năm giờ chiều cho bản online, tám giờ tối cho bản in."}],phrases:[{t:"The big one is the flood in the central region. Lan, can you cover it?",v:"Tin lớn là lũ ở miền Trung. Lan, em đưa tin được không?"},{t:"Yes, take a photographer with you. We need photos by three p.m.",v:"Có, em đi cùng một phóng viên ảnh. Cần ảnh trước ba giờ chiều."},{t:"Nam will write about the new interest rates. Check the facts with the central bank.",v:"Nam sẽ viết về lãi suất mới. Kiểm tra số liệu với ngân hàng nhà nước nhé."},{t:"Five p.m. for online, eight p.m. for the print edition.",v:"Năm giờ chiều cho bản online, tám giờ tối cho bản in."}],notes:[{h:"cover a story",b:"Cover là đưa tin, theo dõi một sự kiện."},{h:"Check the facts",b:"Kiểm chứng thông tin là việc quan trọng nhất của nhà báo."}]},
 {id:"en-w-design-brief",title:"Nhận yêu cầu thiết kế",scene:"Bạn là nhà thiết kế, nhận yêu cầu làm logo từ khách hàng.",partner:"Khách hàng",ind:"design",work:true,lines:[{r:"A",t:"We need a new logo for our coffee shop.",v:"Chúng tôi cần logo mới cho quán cà phê."},{r:"B",t:"Sure. Can you tell me about your brand and your customers?",v:"Được ạ. Anh kể cho tôi về thương hiệu và khách hàng của anh nhé?"},{r:"A",t:"We're a small shop. Our customers are mostly students.",v:"Chúng tôi là quán nhỏ. Khách chủ yếu là sinh viên."},{r:"B",t:"What feeling do you want people to have when they see the logo?",v:"Anh muốn mọi người có cảm giác gì khi nhìn logo?"},{r:"A",t:"Warm, friendly and a bit modern.",v:"Ấm áp, thân thiện và hơi hiện đại."},{r:"B",t:"Do you have any colors in mind?",v:"Anh có nghĩ sẵn màu nào không?"},{r:"A",t:"Brown and cream, maybe.",v:"Có lẽ màu nâu và màu kem."},{r:"B",t:"Great. I'll send you three concepts next Wednesday.",v:"Tuyệt. Thứ Tư tuần sau tôi gửi anh ba phương án."}],phrases:[{t:"Sure. Can you tell me about your brand and your customers?",v:"Được ạ. Anh kể cho tôi về thương hiệu và khách hàng của anh nhé?"},{t:"What feeling do you want people to have when they see the logo?",v:"Anh muốn mọi người có cảm giác gì khi nhìn logo?"},{t:"Do you have any colors in mind?",v:"Anh có nghĩ sẵn màu nào không?"},{t:"Great. I'll send you three concepts next Wednesday.",v:"Tuyệt. Thứ Tư tuần sau tôi gửi anh ba phương án."}],notes:[{h:"brief",b:"Brief là bản yêu cầu thiết kế: thương hiệu, khách hàng, cảm xúc, màu sắc, hạn chót."},{h:"have … in mind",b:"\"Do you have any colors in mind?\" là anh có nghĩ sẵn màu nào chưa."}]},
 {id:"en-w-design-feedback",title:"Nhận góp ý và chỉnh sửa",scene:"Khách hàng xem bản nháp và góp ý. Bạn ghi nhận và đề xuất chỉnh sửa.",partner:"Khách hàng",ind:"design",work:true,lines:[{r:"A",t:"I like the second design, but the text is hard to read.",v:"Tôi thích mẫu thứ hai, nhưng chữ khó đọc."},{r:"B",t:"Thanks for the feedback. I can make the font bigger and bolder.",v:"Cảm ơn góp ý. Tôi có thể làm chữ to và đậm hơn."},{r:"A",t:"Also, the brown is too dark.",v:"Ngoài ra, màu nâu đậm quá."},{r:"B",t:"I'll try a lighter brown and send you two options.",v:"Tôi sẽ thử màu nâu nhạt hơn và gửi anh hai lựa chọn."},{r:"A",t:"How many revisions are included?",v:"Được chỉnh sửa bao nhiêu lần?"},{r:"B",t:"Three rounds of revisions are included in the price.",v:"Giá đã bao gồm ba lần chỉnh sửa."},{r:"A",t:"Good. When can I see it?",v:"Tốt. Khi nào tôi xem được?"},{r:"B",t:"By Friday afternoon. After you approve it, I'll send all the final files.",v:"Trước chiều thứ Sáu. Sau khi anh duyệt, tôi gửi toàn bộ file hoàn chỉnh."}],phrases:[{t:"Thanks for the feedback. I can make the font bigger and bolder.",v:"Cảm ơn góp ý. Tôi có thể làm chữ to và đậm hơn."},{t:"I'll try a lighter brown and send you two options.",v:"Tôi sẽ thử màu nâu nhạt hơn và gửi anh hai lựa chọn."},{t:"Three rounds of revisions are included in the price.",v:"Giá đã bao gồm ba lần chỉnh sửa."},{t:"By Friday afternoon. After you approve it, I'll send all the final files.",v:"Trước chiều thứ Sáu. Sau khi anh duyệt, tôi gửi toàn bộ file hoàn chỉnh."}],notes:[{h:"So sánh hơn",b:"bigger, bolder, lighter: tính từ ngắn + er. \"Too dark\" là quá tối."},{h:"revision",b:"Revision là một lần chỉnh sửa. Three rounds of revisions là ba vòng chỉnh sửa."}]},
 {id:"en-w-design-pitch",title:"Trình bày ý tưởng sáng tạo",scene:"Bạn trình bày ý tưởng chiến dịch quảng cáo cho khách hàng.",partner:"Khách hàng",ind:"design",work:true,lines:[{r:"A",t:"So, what's your idea?",v:"Vậy ý tưởng của anh là gì?"},{r:"B",t:"Our idea is called \"Small moments\". We show real people enjoying your tea in daily life.",v:"Ý tưởng của chúng tôi tên là \"Khoảnh khắc nhỏ\". Chúng tôi cho thấy người thật thưởng thức trà của anh trong đời sống hằng ngày."},{r:"A",t:"Why real people?",v:"Sao lại là người thật?"},{r:"B",t:"Young customers trust real stories more than perfect ads.",v:"Khách hàng trẻ tin câu chuyện thật hơn những quảng cáo hoàn hảo."},{r:"A",t:"What will we make?",v:"Chúng ta sẽ làm gì?"},{r:"B",t:"Six short videos, a set of posters and a photo contest on Instagram.",v:"Sáu video ngắn, một bộ áp phích và một cuộc thi ảnh trên Instagram."},{r:"A",t:"I like it. What's the budget?",v:"Tôi thích. Ngân sách bao nhiêu?"},{r:"B",t:"Around four hundred million dong. I'll send a detailed breakdown today.",v:"Khoảng bốn trăm triệu đồng. Hôm nay tôi sẽ gửi bảng chi tiết."}],phrases:[{t:"Our idea is called \"Small moments\". We show real people enjoying your tea in daily life.",v:"Ý tưởng của chúng tôi tên là \"Khoảnh khắc nhỏ\". Chúng tôi cho thấy người thật thưởng thức trà của anh trong đời sống hằng ngày."},{t:"Young customers trust real stories more than perfect ads.",v:"Khách hàng trẻ tin câu chuyện thật hơn những quảng cáo hoàn hảo."},{t:"Six short videos, a set of posters and a photo contest on Instagram.",v:"Sáu video ngắn, một bộ áp phích và một cuộc thi ảnh trên Instagram."},{t:"Around four hundred million dong. I'll send a detailed breakdown today.",v:"Khoảng bốn trăm triệu đồng. Hôm nay tôi sẽ gửi bảng chi tiết."}],notes:[{h:"Đặt tên cho ý tưởng",b:"Một cái tên ngắn (\"Small moments\") giúp khách dễ nhớ ý tưởng."},{h:"breakdown",b:"Breakdown là bảng chi tiết từng khoản chi phí."}]},
 {id:"en-w-cs-call",title:"Tiếp nhận cuộc gọi hỗ trợ",scene:"Bạn làm tổng đài, khách gọi báo mạng internet bị mất.",partner:"Khách hàng",ind:"cs",work:true,lines:[{r:"A",t:"Hi, my internet isn't working.",v:"Chào em, mạng internet nhà tôi không dùng được."},{r:"B",t:"I'm sorry to hear that. Can I have your account number, please?",v:"Em rất tiếc. Anh cho em xin số tài khoản khách hàng được không ạ?"},{r:"A",t:"It's 0912 345 678.",v:"Là 0912 345 678."},{r:"B",t:"Thank you. Have you tried turning the modem off and on again?",v:"Cảm ơn anh. Anh đã thử tắt modem rồi bật lại chưa ạ?"},{r:"A",t:"Yes, twice. The red light is still on.",v:"Rồi, hai lần. Đèn đỏ vẫn sáng."},{r:"B",t:"I see. There may be a problem with the cable. I'll send a technician.",v:"Em hiểu. Có thể dây cáp bị lỗi. Em sẽ cử kỹ thuật viên đến."},{r:"A",t:"When can he come?",v:"Khi nào anh ấy đến được?"},{r:"B",t:"Tomorrow between nine and eleven a.m. Is that OK for you?",v:"Ngày mai từ chín đến mười một giờ sáng. Giờ đó có tiện cho anh không ạ?"}],phrases:[{t:"I'm sorry to hear that. Can I have your account number, please?",v:"Em rất tiếc. Anh cho em xin số tài khoản khách hàng được không ạ?"},{t:"Thank you. Have you tried turning the modem off and on again?",v:"Cảm ơn anh. Anh đã thử tắt modem rồi bật lại chưa ạ?"},{t:"I see. There may be a problem with the cable. I'll send a technician.",v:"Em hiểu. Có thể dây cáp bị lỗi. Em sẽ cử kỹ thuật viên đến."},{t:"Tomorrow between nine and eleven a.m. Is that OK for you?",v:"Ngày mai từ chín đến mười một giờ sáng. Giờ đó có tiện cho anh không ạ?"}],notes:[{h:"Thể hiện sự đồng cảm",b:"\"I'm sorry to hear that\" trước khi hỏi thông tin giúp khách thấy được lắng nghe."},{h:"Have you tried + V-ing?",b:"\"Have you tried turning it off and on again?\" là anh đã thử tắt rồi bật lại chưa."}]},
 {id:"en-w-cs-complaint",title:"Xử lý khiếu nại",scene:"Khách hàng khiếu nại vì nhận sai hàng. Bạn xử lý khiếu nại.",partner:"Khách hàng",ind:"cs",work:true,lines:[{r:"A",t:"I ordered a black jacket, but you sent me a blue one!",v:"Tôi đặt áo khoác đen mà các bạn gửi áo xanh!"},{r:"B",t:"I'm very sorry about that. I completely understand your frustration.",v:"Em thành thật xin lỗi. Em hoàn toàn hiểu sự bực mình của chị."},{r:"A",t:"I need it for a trip on Saturday.",v:"Tôi cần nó cho chuyến đi thứ Bảy."},{r:"B",t:"Let me check. Yes, we have the black one in your size.",v:"Để em kiểm tra. Vâng, chúng em còn áo đen đúng cỡ của chị."},{r:"A",t:"Can you send it before Saturday?",v:"Gửi trước thứ Bảy được không?"},{r:"B",t:"I'll send it by express delivery today. You'll get it tomorrow.",v:"Em sẽ gửi chuyển phát nhanh hôm nay. Ngày mai chị nhận được."},{r:"A",t:"What about the blue one?",v:"Còn áo xanh thì sao?"},{r:"B",t:"Our driver will pick it up when he delivers the new one. It's free of charge.",v:"Tài xế sẽ lấy lại khi giao áo mới. Hoàn toàn miễn phí."}],phrases:[{t:"I'm very sorry about that. I completely understand your frustration.",v:"Em thành thật xin lỗi. Em hoàn toàn hiểu sự bực mình của chị."},{t:"Let me check. Yes, we have the black one in your size.",v:"Để em kiểm tra. Vâng, chúng em còn áo đen đúng cỡ của chị."},{t:"I'll send it by express delivery today. You'll get it tomorrow.",v:"Em sẽ gửi chuyển phát nhanh hôm nay. Ngày mai chị nhận được."},{t:"Our driver will pick it up when he delivers the new one. It's free of charge.",v:"Tài xế sẽ lấy lại khi giao áo mới. Hoàn toàn miễn phí."}],notes:[{h:"Quy trình xử lý khiếu nại",b:"Xin lỗi → thấu hiểu → kiểm tra → giải pháp cụ thể → miễn phí cho khách."},{h:"frustration",b:"\"I understand your frustration\" là em hiểu chị đang bực mình."}]},
 {id:"en-w-cs-follow",title:"Gọi lại khảo sát hài lòng",scene:"Bạn gọi lại cho khách sau khi đã xử lý sự cố, hỏi mức độ hài lòng.",partner:"Khách hàng",ind:"cs",work:true,lines:[{r:"A",t:"Hello?",v:"A lô?"},{r:"B",t:"Hello, this is Linh from VNet. I'm calling about your internet problem last week.",v:"Chào anh, em là Linh từ VNet. Em gọi về sự cố internet tuần trước của anh."},{r:"A",t:"Oh, yes. It's working fine now.",v:"À vâng. Giờ chạy tốt rồi."},{r:"B",t:"That's great to hear. Was the technician helpful?",v:"Vui quá ạ. Kỹ thuật viên có hỗ trợ tốt không ạ?"},{r:"A",t:"Yes, he was quick and polite.",v:"Có, anh ấy nhanh và lịch sự."},{r:"B",t:"On a scale of one to ten, how satisfied are you with our service?",v:"Trên thang điểm từ một đến mười, anh hài lòng với dịch vụ ở mức nào ạ?"},{r:"A",t:"I'd say eight.",v:"Chắc là tám."},{r:"B",t:"Thank you. Is there anything we could do better?",v:"Cảm ơn anh. Có điều gì chúng em có thể làm tốt hơn không ạ?"}],phrases:[{t:"Hello, this is Linh from VNet. I'm calling about your internet problem last week.",v:"Chào anh, em là Linh từ VNet. Em gọi về sự cố internet tuần trước của anh."},{t:"That's great to hear. Was the technician helpful?",v:"Vui quá ạ. Kỹ thuật viên có hỗ trợ tốt không ạ?"},{t:"On a scale of one to ten, how satisfied are you with our service?",v:"Trên thang điểm từ một đến mười, anh hài lòng với dịch vụ ở mức nào ạ?"},{t:"Thank you. Is there anything we could do better?",v:"Cảm ơn anh. Có điều gì chúng em có thể làm tốt hơn không ạ?"}],notes:[{h:"On a scale of one to ten",b:"Câu hỏi khảo sát phổ biến: trên thang từ một đến mười…"},{h:"Hỏi để cải thiện",b:"\"Is there anything we could do better?\" lịch sự hơn \"Any problems?\""}]},
 {id:"en-w-beauty-book",title:"Đặt lịch hẹn spa",scene:"Bạn là lễ tân spa, nhận cuộc gọi đặt lịch.",partner:"Khách hàng",ind:"beauty",work:true,lines:[{r:"A",t:"Hi, I'd like to book a massage.",v:"Chào em, chị muốn đặt lịch massage."},{r:"B",t:"Sure. Which massage would you like, body or foot?",v:"Vâng ạ. Chị muốn massage body hay massage chân?"},{r:"A",t:"A full body massage, please.",v:"Massage toàn thân nhé."},{r:"B",t:"We have sixty or ninety minutes. Which do you prefer?",v:"Bên em có loại sáu mươi hoặc chín mươi phút. Chị thích loại nào?"},{r:"A",t:"Ninety minutes. Is Saturday afternoon free?",v:"Chín mươi phút. Chiều thứ Bảy có trống không?"},{r:"B",t:"We have a slot at three p.m. Would you like a male or female therapist?",v:"Bên em còn suất lúc ba giờ chiều. Chị muốn kỹ thuật viên nam hay nữ?"},{r:"A",t:"Female, please.",v:"Nữ nhé."},{r:"B",t:"Great, you're booked for Saturday at three. Please arrive ten minutes early.",v:"Dạ, chị đã được đặt lịch thứ Bảy lúc ba giờ. Chị đến sớm mười phút nhé."}],phrases:[{t:"Sure. Which massage would you like, body or foot?",v:"Vâng ạ. Chị muốn massage body hay massage chân?"},{t:"We have sixty or ninety minutes. Which do you prefer?",v:"Bên em có loại sáu mươi hoặc chín mươi phút. Chị thích loại nào?"},{t:"We have a slot at three p.m. Would you like a male or female therapist?",v:"Bên em còn suất lúc ba giờ chiều. Chị muốn kỹ thuật viên nam hay nữ?"},{t:"Great, you're booked for Saturday at three. Please arrive ten minutes early.",v:"Dạ, chị đã được đặt lịch thứ Bảy lúc ba giờ. Chị đến sớm mười phút nhé."}],notes:[{h:"Which do you prefer?",b:"Câu hỏi lựa chọn lịch sự, khi đã đưa hai phương án."},{h:"slot",b:"Slot là khung giờ còn trống. \"We have a slot at three.\""}]},
 {id:"en-w-beauty-skin",title:"Tư vấn chăm sóc da",scene:"Bạn là chuyên viên da, tư vấn cho khách bị da dầu và mụn.",partner:"Khách hàng",ind:"beauty",work:true,lines:[{r:"A",t:"My skin is very oily and I often get spots.",v:"Da chị rất dầu và hay bị mụn."},{r:"B",t:"Let me have a look. Yes, your pores are a bit blocked.",v:"Để em xem. Vâng, lỗ chân lông của chị hơi bị bít."},{r:"A",t:"What should I do?",v:"Chị nên làm gì?"},{r:"B",t:"I recommend a deep cleansing facial once every two weeks.",v:"Em khuyên chị làm sạch sâu da mặt hai tuần một lần."},{r:"A",t:"And at home?",v:"Còn ở nhà?"},{r:"B",t:"Wash your face twice a day with a gentle cleanser, and always use sunscreen.",v:"Rửa mặt ngày hai lần với sữa rửa mặt dịu nhẹ và luôn dùng kem chống nắng."},{r:"A",t:"Should I stop using cream?",v:"Chị có nên bỏ kem dưỡng không?"},{r:"B",t:"No, oily skin still needs moisture. Just choose a light, oil-free moisturizer.",v:"Không ạ, da dầu vẫn cần độ ẩm. Chị chỉ cần chọn kem dưỡng nhẹ, không dầu."}],phrases:[{t:"Let me have a look. Yes, your pores are a bit blocked.",v:"Để em xem. Vâng, lỗ chân lông của chị hơi bị bít."},{t:"I recommend a deep cleansing facial once every two weeks.",v:"Em khuyên chị làm sạch sâu da mặt hai tuần một lần."},{t:"Wash your face twice a day with a gentle cleanser, and always use sunscreen.",v:"Rửa mặt ngày hai lần với sữa rửa mặt dịu nhẹ và luôn dùng kem chống nắng."},{t:"No, oily skin still needs moisture. Just choose a light, oil-free moisturizer.",v:"Không ạ, da dầu vẫn cần độ ẩm. Chị chỉ cần chọn kem dưỡng nhẹ, không dầu."}],notes:[{h:"I recommend…",b:"Chuyên viên dùng \"I recommend…\" để đưa lời khuyên chuyên môn."},{h:"oil-free",b:"Hậu tố -free là \"không có\": oil-free, sugar-free, alcohol-free."}]},
 {id:"en-w-beauty-hair",title:"Tư vấn kiểu tóc",scene:"Bạn là thợ làm tóc, tư vấn kiểu tóc cho khách.",partner:"Khách hàng",ind:"beauty",work:true,lines:[{r:"A",t:"I want a new look, but I'm not sure what.",v:"Tôi muốn đổi kiểu, nhưng chưa biết kiểu gì."},{r:"B",t:"How much time do you spend on your hair every morning?",v:"Mỗi sáng chị dành bao nhiêu thời gian cho tóc?"},{r:"A",t:"Not much, maybe five minutes.",v:"Không nhiều, chắc năm phút."},{r:"B",t:"Then a shoulder-length cut with layers would be easy for you.",v:"Vậy cắt ngang vai, tỉa tầng sẽ dễ cho chị."},{r:"A",t:"What about color?",v:"Còn màu tóc?"},{r:"B",t:"A soft brown would suit your skin tone.",v:"Màu nâu nhẹ sẽ hợp với tông da của chị."},{r:"A",t:"Will dyeing damage my hair?",v:"Nhuộm có làm hư tóc không?"},{r:"B",t:"We use a gentle dye, and I'll add a treatment to protect it.",v:"Bên em dùng thuốc nhuộm dịu nhẹ, và em sẽ thêm hấp dưỡng để bảo vệ tóc."}],phrases:[{t:"How much time do you spend on your hair every morning?",v:"Mỗi sáng chị dành bao nhiêu thời gian cho tóc?"},{t:"Then a shoulder-length cut with layers would be easy for you.",v:"Vậy cắt ngang vai, tỉa tầng sẽ dễ cho chị."},{t:"A soft brown would suit your skin tone.",v:"Màu nâu nhẹ sẽ hợp với tông da của chị."},{t:"We use a gentle dye, and I'll add a treatment to protect it.",v:"Bên em dùng thuốc nhuộm dịu nhẹ, và em sẽ thêm hấp dưỡng để bảo vệ tóc."}],notes:[{h:"Hỏi thói quen trước khi tư vấn",b:"Thợ giỏi hỏi về thói quen của khách để chọn kiểu phù hợp."},{h:"suit",b:"\"A soft brown would suit your skin tone\" là màu nâu nhẹ sẽ hợp với tông da của chị."}]},
 {id:"en-w-agri-buy",title:"Thu mua nông sản",scene:"Bạn là nhân viên thu mua, đàm phán mua sầu riêng với chủ vườn.",partner:"Chủ vườn",ind:"agri",work:true,lines:[{r:"A",t:"This year's durian harvest is very good.",v:"Sầu riêng năm nay được mùa lắm."},{r:"B",t:"Great. How many tons can you sell us?",v:"Tuyệt. Anh bán cho bên em được bao nhiêu tấn?"},{r:"A",t:"About twenty tons.",v:"Khoảng hai mươi tấn."},{r:"B",t:"We need durians that meet export standards, with no chemicals.",v:"Bên em cần sầu riêng đạt chuẩn xuất khẩu, không hóa chất."},{r:"A",t:"Mine are all grown with organic fertilizer.",v:"Của tôi trồng toàn phân hữu cơ."},{r:"B",t:"Do you have a growing area code?",v:"Vườn anh có mã số vùng trồng không?"},{r:"A",t:"Yes, we got it last year.",v:"Có, năm ngoái đã được cấp."},{r:"B",t:"Perfect. We'll pay seventy thousand dong per kilo and collect next week.",v:"Tốt quá. Bên em trả bảy mươi nghìn một ký và tuần sau đến thu."}],phrases:[{t:"Great. How many tons can you sell us?",v:"Tuyệt. Anh bán cho bên em được bao nhiêu tấn?"},{t:"We need durians that meet export standards, with no chemicals.",v:"Bên em cần sầu riêng đạt chuẩn xuất khẩu, không hóa chất."},{t:"Do you have a growing area code?",v:"Vườn anh có mã số vùng trồng không?"},{t:"Perfect. We'll pay seventy thousand dong per kilo and collect next week.",v:"Tốt quá. Bên em trả bảy mươi nghìn một ký và tuần sau đến thu."}],notes:[{h:"meet standards",b:"\"Meet export standards\" là đạt tiêu chuẩn xuất khẩu."},{h:"growing area code",b:"Mã số vùng trồng, yêu cầu bắt buộc khi xuất khẩu nông sản sang nhiều thị trường."}]},
 {id:"en-w-agri-tech",title:"Tư vấn kỹ thuật canh tác",scene:"Bạn là kỹ sư nông nghiệp, tư vấn cho nông dân về cây lúa bị bệnh.",partner:"Nông dân",ind:"agri",work:true,lines:[{r:"A",t:"The leaves of my rice plants are turning yellow.",v:"Lá lúa của tôi đang vàng đi."},{r:"B",t:"Let me look. It might be a disease, or not enough nitrogen.",v:"Để tôi xem. Có thể là bệnh, hoặc thiếu đạm."},{r:"A",t:"How can I tell?",v:"Làm sao biết được?"},{r:"B",t:"If there are brown spots, it's a disease. Here there are none, so it's nitrogen.",v:"Nếu có đốm nâu thì là bệnh. Ở đây không có, nên là thiếu đạm."},{r:"A",t:"What should I use?",v:"Tôi nên dùng gì?"},{r:"B",t:"Add urea fertilizer, about five kilos for every thousand square meters.",v:"Bón thêm phân urê, khoảng năm ký cho mỗi một nghìn mét vuông."},{r:"A",t:"When?",v:"Khi nào?"},{r:"B",t:"Early in the morning, when the field has a little water.",v:"Sáng sớm, khi ruộng còn ít nước."}],phrases:[{t:"Let me look. It might be a disease, or not enough nitrogen.",v:"Để tôi xem. Có thể là bệnh, hoặc thiếu đạm."},{t:"If there are brown spots, it's a disease. Here there are none, so it's nitrogen.",v:"Nếu có đốm nâu thì là bệnh. Ở đây không có, nên là thiếu đạm."},{t:"Add urea fertilizer, about five kilos for every thousand square meters.",v:"Bón thêm phân urê, khoảng năm ký cho mỗi một nghìn mét vuông."},{t:"Early in the morning, when the field has a little water.",v:"Sáng sớm, khi ruộng còn ít nước."}],notes:[{h:"Câu điều kiện loại 1",b:"\"If there are brown spots, it's a disease\" là nếu có đốm nâu thì là bệnh."},{h:"might be",b:"\"It might be a disease\" là có thể là bệnh, dùng khi chưa chắc chắn."}]},
 {id:"en-w-agri-farm",title:"Giới thiệu trang trại",scene:"Bạn giới thiệu trang trại rau sạch cho đoàn khách nước ngoài.",partner:"Khách tham quan",ind:"agri",work:true,lines:[{r:"A",t:"How big is this farm?",v:"Trang trại này rộng bao nhiêu?"},{r:"B",t:"It's about five hectares. We grow vegetables and herbs.",v:"Khoảng năm héc-ta. Chúng tôi trồng rau và rau thơm."},{r:"A",t:"Do you use pesticides?",v:"Có dùng thuốc trừ sâu không?"},{r:"B",t:"No. We use natural methods, like insect nets and helpful insects.",v:"Không. Chúng tôi dùng cách tự nhiên như lưới chắn côn trùng và côn trùng có ích."},{r:"A",t:"How do you water the plants?",v:"Tưới cây bằng cách nào?"},{r:"B",t:"We use a drip irrigation system. It saves forty percent of water.",v:"Dùng hệ thống tưới nhỏ giọt, tiết kiệm bốn mươi phần trăm nước."},{r:"A",t:"Where do you sell your vegetables?",v:"Rau bán ở đâu?"},{r:"B",t:"To supermarkets in Ho Chi Minh City, and online directly to families.",v:"Cho siêu thị ở TP. Hồ Chí Minh và bán online trực tiếp đến các gia đình."}],phrases:[{t:"It's about five hectares. We grow vegetables and herbs.",v:"Khoảng năm héc-ta. Chúng tôi trồng rau và rau thơm."},{t:"No. We use natural methods, like insect nets and helpful insects.",v:"Không. Chúng tôi dùng cách tự nhiên như lưới chắn côn trùng và côn trùng có ích."},{t:"We use a drip irrigation system. It saves forty percent of water.",v:"Dùng hệ thống tưới nhỏ giọt, tiết kiệm bốn mươi phần trăm nước."},{t:"To supermarkets in Ho Chi Minh City, and online directly to families.",v:"Cho siêu thị ở TP. Hồ Chí Minh và bán online trực tiếp đến các gia đình."}],notes:[{h:"hectare",b:"Một héc-ta (hectare) bằng mười nghìn mét vuông."},{h:"Nêu lợi ích bằng số liệu",b:"\"It saves forty percent of water\" có số liệu cụ thể, thuyết phục hơn."}]},
 {id:"en-w-energy-solar",title:"Tư vấn lắp điện mặt trời",scene:"Bạn tư vấn lắp điện mặt trời áp mái cho một nhà máy.",partner:"Giám đốc nhà máy",ind:"energy",work:true,lines:[{r:"A",t:"Our electricity bill is very high.",v:"Hóa đơn tiền điện của chúng tôi rất cao."},{r:"B",t:"A rooftop solar system can cut your bill by about thirty percent.",v:"Hệ thống điện mặt trời áp mái có thể giảm hóa đơn khoảng ba mươi phần trăm."},{r:"A",t:"How big should it be?",v:"Hệ thống nên lớn cỡ nào?"},{r:"B",t:"Your roof is about five thousand square meters, so around eight hundred kilowatts.",v:"Mái nhà anh khoảng năm nghìn mét vuông, nên khoảng tám trăm ki-lô-oát."},{r:"A",t:"What's the cost?",v:"Chi phí bao nhiêu?"},{r:"B",t:"About ten billion dong. You'll get your money back in five to six years.",v:"Khoảng mười tỷ đồng. Anh sẽ hoàn vốn trong năm đến sáu năm."},{r:"A",t:"How long do the panels last?",v:"Tấm pin dùng được bao lâu?"},{r:"B",t:"At least twenty-five years, with a twelve-year warranty.",v:"Ít nhất hai mươi lăm năm, bảo hành mười hai năm."}],phrases:[{t:"A rooftop solar system can cut your bill by about thirty percent.",v:"Hệ thống điện mặt trời áp mái có thể giảm hóa đơn khoảng ba mươi phần trăm."},{t:"Your roof is about five thousand square meters, so around eight hundred kilowatts.",v:"Mái nhà anh khoảng năm nghìn mét vuông, nên khoảng tám trăm ki-lô-oát."},{t:"About ten billion dong. You'll get your money back in five to six years.",v:"Khoảng mười tỷ đồng. Anh sẽ hoàn vốn trong năm đến sáu năm."},{t:"At least twenty-five years, with a twelve-year warranty.",v:"Ít nhất hai mươi lăm năm, bảo hành mười hai năm."}],notes:[{h:"cut … by …",b:"\"Cut your bill by thirty percent\" là giảm hóa đơn ba mươi phần trăm."},{h:"get your money back",b:"Hoàn vốn. Từ chuyên ngành: payback period (thời gian hoàn vốn)."}]},
 {id:"en-w-energy-plant",title:"Vận hành nhà máy điện",scene:"Bạn là kỹ sư vận hành, báo cáo tình hình ca trực tại nhà máy điện gió.",partner:"Trưởng ca",ind:"energy",work:true,lines:[{r:"A",t:"How was the night shift?",v:"Ca đêm thế nào?"},{r:"B",t:"Mostly normal. The wind was strong, so output was high.",v:"Phần lớn bình thường. Gió mạnh nên sản lượng cao."},{r:"A",t:"Any problems?",v:"Có sự cố gì không?"},{r:"B",t:"Turbine number six stopped at 2 a.m. because of a sensor error.",v:"Tua-bin số sáu dừng lúc hai giờ sáng do lỗi cảm biến."},{r:"A",t:"Is it running now?",v:"Giờ đã chạy chưa?"},{r:"B",t:"Not yet. The maintenance team will replace the sensor this morning.",v:"Chưa. Đội bảo trì sẽ thay cảm biến sáng nay."},{r:"A",t:"What was the total output?",v:"Tổng sản lượng là bao nhiêu?"},{r:"B",t:"About three hundred megawatt hours. I've written everything in the shift log.",v:"Khoảng ba trăm megawatt giờ. Em đã ghi hết vào sổ trực ca."}],phrases:[{t:"Mostly normal. The wind was strong, so output was high.",v:"Phần lớn bình thường. Gió mạnh nên sản lượng cao."},{t:"Turbine number six stopped at 2 a.m. because of a sensor error.",v:"Tua-bin số sáu dừng lúc hai giờ sáng do lỗi cảm biến."},{t:"Not yet. The maintenance team will replace the sensor this morning.",v:"Chưa. Đội bảo trì sẽ thay cảm biến sáng nay."},{t:"About three hundred megawatt hours. I've written everything in the shift log.",v:"Khoảng ba trăm megawatt giờ. Em đã ghi hết vào sổ trực ca."}],notes:[{h:"Báo cáo ca trực",b:"Tình hình chung → sự cố → hành động khắc phục → số liệu → đã ghi sổ."},{h:"output",b:"Output là sản lượng điện phát ra."}]},
 {id:"en-w-energy-save",title:"Tư vấn tiết kiệm năng lượng",scene:"Bạn là chuyên gia kiểm toán năng lượng, trình bày kết quả cho một khách sạn.",partner:"Quản lý khách sạn",ind:"energy",work:true,lines:[{r:"A",t:"What did you find in the audit?",v:"Kiểm toán thấy những gì?"},{r:"B",t:"Air conditioning uses sixty percent of your energy.",v:"Điều hòa tiêu thụ sáu mươi phần trăm năng lượng của khách sạn."},{r:"A",t:"That's a lot. What can we do?",v:"Nhiều thật. Chúng tôi làm được gì?"},{r:"B",t:"First, set the temperature to twenty-six degrees in empty rooms.",v:"Trước tiên, đặt nhiệt độ hai mươi sáu độ ở phòng trống."},{r:"A",t:"What else?",v:"Còn gì nữa?"},{r:"B",t:"Replace old lights with LEDs and install key-card switches in every room.",v:"Thay đèn cũ bằng đèn LED và lắp công tắc thẻ từ ở mọi phòng."},{r:"A",t:"How much will we save?",v:"Chúng tôi tiết kiệm được bao nhiêu?"},{r:"B",t:"Around twenty percent a year, and guests won't notice any difference.",v:"Khoảng hai mươi phần trăm mỗi năm, mà khách không nhận thấy khác biệt."}],phrases:[{t:"Air conditioning uses sixty percent of your energy.",v:"Điều hòa tiêu thụ sáu mươi phần trăm năng lượng của khách sạn."},{t:"First, set the temperature to twenty-six degrees in empty rooms.",v:"Trước tiên, đặt nhiệt độ hai mươi sáu độ ở phòng trống."},{t:"Replace old lights with LEDs and install key-card switches in every room.",v:"Thay đèn cũ bằng đèn LED và lắp công tắc thẻ từ ở mọi phòng."},{t:"Around twenty percent a year, and guests won't notice any difference.",v:"Khoảng hai mươi phần trăm mỗi năm, mà khách không nhận thấy khác biệt."}],notes:[{h:"audit",b:"Energy audit là kiểm toán năng lượng, đo xem năng lượng dùng vào đâu."},{h:"First… / What else?",b:"Đưa giải pháp theo thứ tự ưu tiên, bắt đầu với cách rẻ và dễ nhất."}]}
